    on(type, fn) { t.addEventListener(type, fn); return () => t.removeEventListener(type, fn); },
    emit(type, detail = {}) { t.dispatchEvent(new CustomEvent(type, { detail })); try { if (ch) ch.postMessage({ type, detail }); } catch (_) { /* ignore */ } }
