const ROLE_TONE = { department: 'sky', technician: 'teal', support_manager: 'violet', supervisor: 'brass', monitor: 'slate' };
const genPassword = () => { const a = 'abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ', d = '23456789', b = new Uint8Array(10); crypto.getRandomValues(b); let s = Array.from(b.slice(0, 7), (x) => a[x % a.length]).join('') + Array.from(b.slice(7), (x) => d[x % d.length]).join(''); return s; };

/* ── الملف الشخصي والتخصيص ──────────────────────────────────── */
Pages.profile = async (ctx) => {
  const draw = async () => {
    const u = Auth.user, m = await Medals.compute(u), acts = [];
    await DB.each('activity', { index: 'at', dir: 'prev' }, (a) => { if (a.userId === u.id) acts.push(a); if (acts.length >= 8) return false; });
    if (!ctx.alive()) return;
    const theme = localStorage.getItem('sq_theme') || 'auto', accent = document.documentElement.dataset.accent, hue = UI.hueOf(u);
    ctx.view.innerHTML = String(html`
      ${u.mustChangePassword ? html`<div class="banner tone-amber">${UI.icon('lock')}<div class="grow"><b>يجب تغيير كلمة المرور المؤقتة قبل المتابعة</b><div class="small muted">اختر كلمة مرور خاصة بك من 8 أحرف على الأقل تتضمن حروفاً وأرقاماً.</div></div></div>` : ''}
      <section class="profile-hero"><div class="avatar-edit">${UI.avatar(u, 'av-xl')}<button class="icon-btn" data-act="photo" title="تغيير الصورة" aria-label="تغيير الصورة">${UI.icon('upload')}</button></div>
        <div><h1>${u.name}</h1><div class="row" style="margin-top:6px">${UI.chip(ROLE_TONE[u.role] || 'slate', ROLES[u.role], 'shield')}<span class="faint">@${u.username}</span><span class="faint">${Data.nameOf('departments', u.departmentId, '')}</span></div><p class="small faint" style="margin-top:6px">آخر دخول ${u.lastLoginAt ? fmtDateTime(u.lastLoginAt) : '—'}</p></div>
        <div class="profile-stats"><div><b data-count="${m.submitted}">0</b><small>بلاغ قدّمته</small></div>${m.staff ? html`<div><b data-count="${m.resolved}">0</b><small>بلاغ حللته</small></div>` : ''}</div>
      </section>
      <div class="grid g-2">
        ${UI.panel({ title: 'تخصيص المظهر', icon: 'sliders', body: html`<div class="stack" style="gap:18px">
          <div class="field"><label>المظهر</label><div class="seg">${[['dark', 'داكن', 'moon'], ['light', 'فاتح', 'sun'], ['auto', 'حسب الجهاز', 'monitor']].map(([k, l, ic]) => html`<label><input type="radio" name="theme" value="${k}"${theme === k ? raw(' checked') : ''}><span>${UI.icon(ic)}${l}</span></label>`)}</div></div>
          <div class="field"><label>لون التمييز</label><div class="swatches">${[['brass', 'نحاسي'], ['teal', 'فيروزي'], ['sky', 'سماوي'], ['violet', 'بنفسجي'], ['red', 'قرمزي']].map(([k, l]) => html`<button class="swatch tone-${k} ${accent === k ? 'active' : ''}" data-accent="${k}" title="${l}" aria-label="${l}"></button>`)}</div></div>
          <div class="field"><label>لون الصورة الرمزية</label><div class="hues">${[210, 250, 280, 330, 0, 25, 45, 150, 175, 195].map((h) => html`<button style="--h:${h}" class="${h === hue ? 'active' : ''}" data-hue="${h}" aria-label="لون ${h}"></button>`)}</div></div>
          <div class="row" style="gap:22px">${UI.field({ name: 'motion', type: 'switch', text: 'الحركات والمؤثرات' }, document.documentElement.dataset.motion !== 'off')}${UI.field({ name: 'sound', type: 'switch', text: 'أصوات التنبيه' }, localStorage.getItem('sq_sound') === 'on')}</div>
          ${u.photo ? html`<button class="btn btn-ghost btn-sm" data-act="nophoto" style="align-self:flex-start">${UI.icon('trash')} حذف الصورة الشخصية</button>` : ''}
        </div>` })}
        ${isSysAccount(u) && u.role !== 'supervisor' ? UI.panel({ title: 'كلمة المرور', icon: 'lock', body: html`<div class="banner tone-brass" style="margin:0">${UI.icon('shield')}<div class="grow"><b>حساب أساسي ثابت</b><div class="small muted">اسم المستخدم وكلمة المرور لهذا الحساب ثابتان، ولا يغيّرهما إلا المشرف. يمكنك تخصيص المظهر والصورة من هذه الصفحة.</div></div></div>` }) : UI.panel({ title: 'تغيير كلمة المرور', icon: 'lock', body: html`<form id="pwForm" class="stack" style="gap:14px" novalidate>${UI.field({ name: 'current', label: 'كلمة المرور الحالية', type: 'password', autocomplete: 'current-password', required: true })}${UI.field({ name: 'next', label: 'كلمة المرور الجديدة', type: 'password', autocomplete: 'new-password', required: true })}<div class="strength" id="pwStr"><i></i><i></i><i></i><i></i></div>${UI.field({ name: 'confirm', label: 'تأكيد كلمة المرور الجديدة', type: 'password', autocomplete: 'new-password', required: true })}<button class="btn btn-primary" type="submit">${UI.icon('check')} تحديث كلمة المرور</button></form>` })}
      </div>
      ${UI.panel({ title: 'نشاطي الأخير', icon: 'pulse', cls: 'mt', body: acts.length ? html`<div class="timeline">${acts.map((a) => html`<div class="tl"><span class="tl-icon tone-${ACT_TONE[a.action] || 'slate'}">${UI.icon(ACT_ICON[a.action] || 'pulse')}</span><div class="tl-head">${a.summary}<span class="tl-time">${timeAgo(a.at)}</span></div></div>`)}</div>` : UI.noData('لا يوجد نشاط مسجل بعد') })}`);
    const pwf = $('#pwForm', ctx.view);
    if (!pwf) return;
    pwf.querySelector('[name="next"]').addEventListener('input', (e) => { $('#pwStr', ctx.view).dataset.s = e.target.value ? Data.users.strength(e.target.value) : 0; });
    pwf.addEventListener('submit', async (e) => {
      e.preventDefault(); const v = UI.formValues(pwf), btn = pwf.querySelector('[type=submit]');
      try {
        if (v.next !== v.confirm) throw new AppError('كلمتا المرور الجديدتان غير متطابقتين');
        if (v.next === v.current) throw new AppError('اختر كلمة مرور مختلفة عن الحالية');
        UI.busy(btn, true); await new Promise((r) => setTimeout(r, 40));
        const rec = await DB.get('users', u.id); if (!(await Crypto.verifyPassword(v.current, rec.pass))) throw new AppError('كلمة المرور الحالية غير صحيحة');
        const forced = u.mustChangePassword; await Data.users.setPassword(u.id, v.next, false); Auth.user = await DB.get('users', u.id);
        UI.toast('تم تحديث كلمة المرور بنجاح'); UI.confetti();
        if (forced) { Shell.unmount(); Router.go('/dashboard'); } else pwf.reset();
      } catch (ex) { UI.error(ex); } finally { UI.busy(btn, false); }
    });
  };
  const saveUser = async (patch) => { const rec = await DB.get('users', Auth.user.id); Object.assign(rec, patch, { updatedAt: now() }); await DB.put('users', rec); await Data.refresh('users'); Auth.user = rec; Shell.unmount(); await Router.resolve(); };
  UI.on(ctx.view, 'change', 'input[name="theme"]', (e, el) => { if (el.value === 'auto') { localStorage.removeItem('sq_theme'); UI.theme.apply(); } else UI.theme.set('theme', el.value); });
  UI.on(ctx.view, 'click', '[data-accent]', (e, el) => { UI.theme.set('accent', el.dataset.accent); $$('[data-accent]', ctx.view).forEach((b) => b.classList.toggle('active', b === el)); UI.sound('notify'); });
  UI.on(ctx.view, 'click', '[data-hue]', (e, el) => saveUser({ prefs: { ...(Auth.user.prefs || {}), hue: Number(el.dataset.hue) } }));
  UI.on(ctx.view, 'change', 'input[name="motion"]', (e, el) => UI.theme.set('motion', el.checked ? 'on' : 'off'));
  UI.on(ctx.view, 'change', 'input[name="sound"]', (e, el) => { localStorage.setItem('sq_sound', el.checked ? 'on' : 'off'); UI.sound('success'); });
  UI.on(ctx.view, 'click', '[data-act="photo"]', async () => { const [f] = await UI.pickFiles({ accept: 'image/*', multiple: false }); if (!f) return; try { await saveUser({ photo: await UI.resizeImage(f, 180) }); UI.toast('تم تحديث الصورة الشخصية'); } catch (ex) { UI.error(ex); } });
  UI.on(ctx.view, 'click', '[data-act="nophoto"]', () => saveUser({ photo: '' }));
  await draw();
};
const ACT_ICON = { create: 'plus', update: 'edit', delete: 'trash', login: 'key', logout: 'logout', password: 'lock', move: 'swap', status: 'refresh', assign: 'user-plus', comment: 'send', rate: 'star' };
const ACT_LABEL = { create: 'إضافة', update: 'تعديل', delete: 'حذف', login: 'تسجيل دخول', logout: 'تسجيل خروج', password: 'كلمة المرور', move: 'حركة مخزون', status: 'تغيير حالة', assign: 'إسناد', comment: 'رد', rate: 'تقييم', backup: 'نسخة احتياطية', lend: 'تسليم عهدة', return: 'إرجاع عهدة', import: 'استيراد', migrate: 'ترحيل' };
const ACT_TONE = { create: 'teal', update: 'sky', delete: 'red', login: 'violet', logout: 'slate', password: 'amber', move: 'amber', status: 'sky', assign: 'violet', comment: 'teal', rate: 'brass' };

/* ── قاعدة المعرفة ─────────────────────────────────────────── */
Pages.kbEditor = async (id) => {
  const a = id ? await DB.get('kb', id) : {};
  return UI.modal({ title: id ? 'تعديل المقال' : 'مقال حل جديد', icon: 'book', size: 'lg', body: UI.fields([{ name: 'title', label: 'عنوان المشكلة', required: true, wide: true }, { name: 'categoryId', label: 'الفئة', type: 'select', options: UI.opts('categories') }, { name: 'keywords', label: 'كلمات مفتاحية للبحث', placeholder: 'مثال: طباعة، ورق، انحشار' }, { name: 'body', label: 'خطوات الحل', type: 'textarea', rows: 10, wide: true, placeholder: '1. ...\n2. ...' }], a), actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'حفظ المقال', kind: 'primary', icon: 'check', submit: true, handler: async (form) => { const v = UI.formValues(form); if (!v.title.trim() || !v.body.trim()) throw new AppError('العنوان وخطوات الحل مطلوبة'); const r = await Data.saveRecord('kb', { ...a, ...v, author: a.author || Auth.user.name, views: a.views || 0, helpful: a.helpful || 0 }, 'مقال'); UI.toast('تم حفظ المقال'); return r; } }] });
};
Pages.kbArticle = async (id) => {
  const a = await Data.kb.view(id).then(() => DB.get('kb', id)); if (!a) return;
  const write = Auth.can('kb.write');
  const r = await UI.modal({ title: a.title, icon: 'book', size: 'lg', body: html`<div class="row" style="margin-bottom:14px">${UI.chip('sky', Data.nameOf('categories', a.categoryId, 'عام'), 'tag')}<span class="kb-meta">${UI.icon('eye')} ${fmtNum(a.views)} مشاهدة ${UI.icon('check')} ${fmtNum(a.helpful)} وجدوه مفيداً</span></div><div class="article">${a.body}</div>${a.author ? html`<p class="small faint mt">كتبه ${a.author} — آخر تحديث ${timeAgo(a.updatedAt || a.createdAt)}</p>` : ''}`, actions: [...(write ? [{ label: 'حذف', kind: 'danger', icon: 'trash', value: 'delete' }, { label: 'تعديل', kind: 'ghost', icon: 'edit', value: 'edit' }] : []), { label: 'لم يحل مشكلتي', kind: 'ghost', value: 'ticket' }, { label: 'مفيد', kind: 'ok', icon: 'check', value: 'vote' }] });
  if (r === 'vote') { await Data.kb.vote(id); UI.toast('شكراً! رأيك يساعد الآخرين'); UI.sound('success'); Bus.emit('data:kb'); }
  else if (r === 'ticket' && Auth.can('tickets.create')) Router.go(`/tickets/new${a.categoryId ? `?cat=${a.categoryId}` : ''}`);
  else if (r === 'edit') { if (await Pages.kbEditor(id)) Bus.emit('data:kb'); }
  else if (r === 'delete' && (await UI.confirm(`حذف المقال «${a.title}» نهائياً؟`, { danger: true, ok: 'حذف' }))) { await Data.deleteRecord('kb', id, 'مقال'); UI.toast('تم حذف المقال'); Bus.emit('data:kb'); }
};
Pages.kb = async (ctx) => {
  const st = { q: '', cat: '' }, write = Auth.can('kb.write');
  ctx.view.innerHTML = String(html`<section class="kb-hero"><div><h1>كيف يمكننا مساعدتك؟</h1><p class="muted">حلول مجرّبة لأكثر المشكلات التقنية شيوعاً في الأكاديمية</p><div class="search-box">${UI.icon('search')}<input id="kbq" type="search" placeholder="اكتب المشكلة، مثل: الطابعة لا تطبع" autocomplete="off"></div><div class="quick-chips" id="kbcats" style="margin-top:14px"></div></div>${UI.illu('software')}</section>
    <div class="row mb" style="justify-content:space-between"><h2 style="font-size:16px" id="kbCount"></h2>${write ? html`<button class="btn btn-primary" data-act="new">${UI.icon('plus')} مقال جديد</button>` : ''}</div><div id="kbList"></div>`);
  const cats = Data.list('categories');
  const chips = () => { $('#kbcats', ctx.view).innerHTML = String(html`<button class="qchip" data-cat="" style="${st.cat ? '' : 'border-style:solid;color:rgb(var(--accent-ink))'}">الكل</button>${cats.map((c) => html`<button class="qchip" data-cat="${c.id}" style="${st.cat === c.id ? 'border-style:solid;color:rgb(var(--accent-ink))' : ''}">${c.name}</button>`)}`); };
  const load = async () => {
    const rows = await Data.kb.search(st.q, st.cat); if (!ctx.alive()) return;
    $('#kbCount', ctx.view).textContent = arCount(rows.length, AR.article);
    $('#kbList', ctx.view).innerHTML = String(rows.length ? html`<div class="grid g-3 stagger">${rows.map((a) => html`<button class="kb-card" data-kb="${a.id}"><div class="row" style="flex-wrap:nowrap">${UI.illu(catIllu(a.categoryId), 'mini')}<b>${a.title}</b></div><p>${a.body}</p><span class="kb-meta">${UI.icon('eye')} ${fmtNum(a.views)} ${UI.icon('check')} ${fmtNum(a.helpful)} ${a.categoryId ? html`<span style="margin-inline-start:auto">${Data.nameOf('categories', a.categoryId)}</span>` : ''}</span></button>`)}</div>` : UI.empty({ illu: 'software', title: 'لم نجد حلاً مطابقاً', text: 'جرّب كلمات أخرى، أو قدّم بلاغاً وسيساعدك فريق الدعم.', action: Auth.can('tickets.create') ? html`<a class="btn btn-primary" href="#/tickets/new">${UI.icon('plus')} بلاغ جديد</a>` : '' }));
  };
  $('#kbq', ctx.view).addEventListener('input', debounce((e) => { st.q = e.target.value; load(); }, 220));
  UI.on(ctx.view, 'click', '[data-cat]', (e, el) => { st.cat = el.dataset.cat; chips(); load(); });
  UI.on(ctx.view, 'click', '[data-kb]', (e, el) => Pages.kbArticle(el.dataset.kb));
  UI.on(ctx.view, 'click', '[data-act="new"]', async () => { if (await Pages.kbEditor()) load(); });
  ctx.onCleanup(Bus.on('data:kb', () => { if (ctx.alive()) load(); }));
  chips(); await load();
  if (ctx.query.open) setTimeout(() => Pages.kbArticle(ctx.query.open), 200);
};

/* ── الإشعارات وسجل النشاط ─────────────────────────────────── */
Pages.notifications = async (ctx) => {
  const st = { unread: false, offset: 0, limit: 40 }, me = Auth.user.id;
  ctx.view.innerHTML = String(html`${UI.pageHead({ title: 'الإشعارات', sub: 'كل ما يخصك من تحديثات', illu: 'bell', actions: html`<label class="switch"><input type="checkbox" id="nUnread"><i></i><span>غير المقروءة فقط</span></label><button class="btn" data-act="readall">${UI.icon('check')} قراءة الكل</button><button class="btn" data-act="delread">${UI.icon('trash')} حذف المقروءة</button>` })}<section class="panel"><div class="panel-body" id="nList"></div></section><p class="hint mt">تُحذف الإشعارات المقروءة تلقائياً بعد ${NOTE_KEEP_DAYS} أيام من فتحها.</p>`);
  const load = async () => {
    const { rows, hasMore } = await DB.page('notifications', { index: 'user_at', range: KR([me, 0], [me, Infinity]), offset: st.offset, limit: st.limit, filter: st.unread ? (n) => !n.read : null }); if (!ctx.alive()) return;
    let last = '';
    $('#nList', ctx.view).innerHTML = String(rows.length ? html`${rows.map((n) => { const day = fmtDate(n.at), headRow = day !== last ? html`<div class="day-head">${startOfDay(n.at) === startOfDay() ? 'اليوم' : startOfDay(n.at) === startOfDay() - DAY ? 'أمس' : day}</div>` : ''; last = day; return html`${headRow}<div class="note tone-${n.kind === 'inventory' ? 'amber' : n.kind === 'ticket' ? 'sky' : 'teal'} ${n.read ? '' : 'unread'}" data-id="${n.id}" data-link="${n.link}"><span class="n-ic">${UI.icon(n.kind === 'inventory' ? 'box' : n.kind === 'ticket' ? 'ticket' : 'bell')}</span><div class="grow"><b>${n.title}</b><small>${n.body || ''}</small></div><small class="faint nowrap">${fmtTime(n.at)}</small><button type="button" class="icon-btn n-del" data-del="${n.id}" aria-label="حذف الإشعار" title="حذف">${UI.icon('x')}</button></div>`; })}${UI.pager({ offset: st.offset, limit: st.limit, count: rows.length, hasMore })}` : UI.empty({ illu: 'bell', title: 'لا توجد إشعارات', text: 'ستصلك هنا تحديثات البلاغات والمخازن.' }));
  };
  $('#nUnread', ctx.view).onchange = (e) => { st.unread = e.target.checked; st.offset = 0; load(); };
  UI.on(ctx.view, 'click', '[data-act="readall"]', async () => { await Data.notes.readAll(); load(); });
  UI.on(ctx.view, 'click', '[data-act="delread"]', async () => { const rows = (await DB.getAll('notifications', 'user_at', KR([me, 0], [me, Infinity]))).filter((n) => n.read); if (!rows.length) { UI.toast('لا توجد إشعارات مقروءة'); return; } await Data.notes.remove(rows.map((n) => n.id)); UI.toast(`حُذف ${fmtNum(rows.length)} إشعار`); Shell.refreshBell(); load(); });
  UI.on(ctx.view, 'click', '.note', async (e, el) => { const d = e.target.closest('[data-del]'); if (d) { e.stopPropagation(); await Data.notes.remove(d.dataset.del); Shell.refreshBell(); load(); return; } await Data.notes.read(el.dataset.id); Shell.refreshBell(); if (el.dataset.link) Router.go(el.dataset.link); else load(); });
  UI.on(ctx.view, 'click', '[data-page]', (e, el) => { st.offset = Math.max(0, st.offset + (el.dataset.page === 'next' ? st.limit : -st.limit)); load(); });
  await load();
};
Pages.activity = async (ctx) => {
  const st = { user: '', action: '', from: '', to: '', offset: 0, limit: 40 };
  ctx.view.innerHTML = String(html`${UI.pageHead({ title: 'سجل النشاط', sub: 'تتبع كامل لكل عملية في النظام: من، ماذا، ومتى', illu: 'cctv', actions: html`<button class="btn" data-act="csv">${UI.icon('download')} تصدير</button>` })}<section class="panel"><div class="toolbar"><select id="aUser" aria-label="المستخدم"><option value="">كل المستخدمين</option>${UI.userOpts().map((o) => html`<option value="${o.value}">${o.label}</option>`)}</select><select id="aAct" aria-label="نوع العملية"><option value="">كل العمليات</option>${Object.keys(ACT_LABEL).map((k) => html`<option value="${k}">${ACT_LABEL[k]}</option>`)}</select><input type="date" dir="ltr" lang="en-GB" id="aFrom" aria-label="من تاريخ"><input type="date" dir="ltr" lang="en-GB" id="aTo" aria-label="إلى تاريخ"></div><div id="aBody"></div></section>`);
  const opts = (all) => ({ index: 'at', range: KR(fromDateInput(st.from), st.to ? fromDateInput(st.to, true) : Infinity), offset: all ? 0 : st.offset, limit: all ? 1e6 : st.limit, filter: st.user || st.action ? (a) => (!st.user || a.userId === st.user) && (!st.action || a.action === st.action) : null });
  const load = async () => {
    const { rows, hasMore } = await DB.page('activity', opts()); if (!ctx.alive()) return;
    $('#aBody', ctx.view).innerHTML = String(rows.length ? html`<div class="table-wrap"><table class="table"><thead><tr><th>الوقت</th><th>المستخدم</th><th>العملية</th><th>التفاصيل</th></tr></thead><tbody class="stagger">${rows.map((a) => html`<tr><td class="nowrap faint">${fmtDateTime(a.at)}</td><td>${a.userId ? html`<div class="row nowrap" style="gap:8px;flex-wrap:nowrap">${UI.avatar(a.userId, 'av-sm')}${Data.userName(a.userId)}</div>` : html`<span class="faint">النظام</span>`}</td><td>${UI.chip(ACT_TONE[a.action] || 'slate', ACT_LABEL[a.action] || a.action, ACT_ICON[a.action] || 'pulse')}</td><td>${a.summary}</td></tr>`)}</tbody></table></div>${UI.pager({ offset: st.offset, limit: st.limit, count: rows.length, hasMore })}` : UI.empty({ illu: 'cctv', title: 'لا يوجد نشاط مطابق', text: 'غيّر عوامل التصفية.' }));
  };
  [['aUser', 'user'], ['aAct', 'action'], ['aFrom', 'from'], ['aTo', 'to']].forEach(([id, k]) => { $('#' + id, ctx.view).onchange = (e) => { st[k] = e.target.value; st.offset = 0; load(); }; });
  UI.on(ctx.view, 'click', '[data-page]', (e, el) => { st.offset = Math.max(0, st.offset + (el.dataset.page === 'next' ? st.limit : -st.limit)); load(); });
  UI.on(ctx.view, 'click', '[data-act="csv"]', async () => { const { rows } = await DB.page('activity', opts(true)); downloadBlob(new Blob([toCSV(rows, [{ label: 'الوقت', value: (a) => fmtDateTime(a.at) }, { label: 'المستخدم', value: (a) => Data.userName(a.userId) }, { label: 'العملية', key: 'action' }, { label: 'الكيان', key: 'entity' }, { label: 'التفاصيل', key: 'summary' }])], { type: 'text/csv;charset=utf-8' }), `سجل-النشاط-${dateInput(now())}.csv`); });
  await load();
};

/* ── الإعدادات والبيانات ───────────────────────────────────── */
const LOOKUPS = {
  departments: { title: 'الأقسام', icon: 'building', fields: [] },
  ranks: { title: 'الرتب', icon: 'shield', fields: [] },
  categories: { title: 'فئات البلاغات', icon: 'tag', illu: true, fields: [] },
  itemCategories: { title: 'تصنيفات الأصناف', icon: 'grid', illu: true, fields: [] },
  warehouses: { title: 'المخازن', icon: 'warehouse', fields: [{ name: 'location', label: 'الموقع' }, { name: 'keeper', label: 'أمين المخزن' }] }
};
Pages.lookupModal = async (store, id) => {
  const L = LOOKUPS[store], rec = id ? Data.c[store].get(id) : { illustration: 'box' };
  return UI.modal({ title: `${id ? 'تعديل' : 'إضافة'}: ${L.title}`, icon: L.icon, size: L.illu ? 'lg' : '', body: html`${UI.fields([{ name: 'name', label: 'الاسم', required: true }, { name: 'order', label: 'الترتيب', type: 'number', min: 0 }, ...L.fields], rec)}${L.illu ? html`<div class="field mt"><label>الرسمة ثلاثية الأبعاد</label><div class="illu-pick">${Iso.names.map((n) => html`<label><input type="radio" name="illustration" value="${n}"${rec.illustration === n ? raw(' checked') : ''}><span>${UI.illu(n)}${ILLU_LABELS[n] || n}</span></label>`)}</div></div>` : ''}`, actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'حفظ', kind: 'primary', icon: 'check', submit: true, handler: async (form) => { const v = UI.formValues(form); if (!String(v.name).trim()) throw new AppError('الاسم مطلوب'); const r = await Data.saveRecord(store, { ...rec, ...v, name: v.name.trim(), order: Number(v.order) || 0 }, L.title); UI.toast('تم الحفظ'); return r; } }] });
};
Pages.settings = async (ctx) => {
  const st = { tab: ctx.query.tab || 'general', lookup: 'departments' };
  const tabs = [['general', 'عام', 'sliders'], ['sla', 'اتفاقية الخدمة', 'clock'], ['lookups', 'القوائم', 'layers'], ['templates', 'الردود الجاهزة', 'send'], ['data', 'البيانات والنسخ الاحتياطي', 'database']];
  const draw = async () => {
    const s = Data.c.settings; let body = '';
    if (st.tab === 'general') body = UI.panel({ title: 'معلومات النظام', icon: 'sliders', body: html`<form id="gForm" novalidate>${UI.fields([{ name: 'orgName', label: 'اسم الجهة', wide: true }, { name: 'systemName', label: 'اسم النظام' }, { name: 'supportPhone', label: 'هاتف الدعم الفني', dir: 'ltr' }, { name: 'sessionHours', label: 'مدة الجلسة بالساعات', type: 'number', min: 1, max: 72 }, { name: 'escalateAfter', label: 'تنبيه المسؤولين بعد تجاوز الموعد بـ (دقيقة)', type: 'number', min: 5, value: s.escalateAfter || 60 }, { name: 'autoStrategy', label: 'توزيع البلاغات عند تعدد المختصين', type: 'select', placeholder: false, options: [{ value: 'least', label: 'الأقل انشغالاً' }, { value: 'round', label: 'بالتناوب' }, { value: 'notify', label: 'إشعار المختصين دون إسناد' }], value: (s.autoAssign || {}).strategy || 'least' }, { name: 'autoCloseDays', label: 'إغلاق البلاغ المحلول تلقائياً بعد (أيام)', type: 'number', min: 1, max: 30, value: s.autoCloseDays || 3 }, { name: 'autoCloseOn', type: 'switch', text: 'الإغلاق التلقائي مع تذكير المستفيد', value: s.autoClose !== 0 }, { name: 'avatars', label: 'الصور الشخصية للحسابات', type: 'select', placeholder: false, options: [{ value: 'off', label: 'معطّلة (توفير المساحة)' }, { value: 'approval', label: 'بموافقة المشرف' }, { value: 'on', label: 'مسموحة للجميع' }], value: s.avatars || 'off' }, { name: 'autoOn', type: 'switch', text: 'الإسناد التلقائي حسب تخصص الفني', value: (s.autoAssign || {}).on !== 0, wide: true }], s)}<button class="btn btn-primary mt" type="submit">${UI.icon('check')} حفظ</button></form>` });
    else if (st.tab === 'sla') body = UI.panel({ title: 'أهداف اتفاقية مستوى الخدمة', icon: 'clock', sub: 'تُحسب مواعيد البلاغات الجديدة وفق هذه الأهداف', flush: true, body: html`<form id="slaForm" novalidate><div class="table-wrap"><table class="table"><thead><tr><th>الأولوية</th><th>أول استجابة (بالدقائق)</th><th>الحل (بالساعات)</th><th>المعاينة</th></tr></thead><tbody>${Object.entries(PRIORITY).map(([k, p]) => html`<tr><td>${UI.priority(k)}</td><td><input class="input" style="max-width:140px" type="number" min="1" name="${k}_respond" value="${s.sla[k].respond}"></td><td><input class="input" style="max-width:140px" type="number" min="1" step="0.5" name="${k}_resolve" value="${s.sla[k].resolve / 60}"></td><td class="faint small">${fmtDuration(s.sla[k].respond * MIN)} / ${fmtDuration(s.sla[k].resolve * MIN)}</td></tr>`)}</tbody></table></div><div class="panel-body"><button class="btn btn-primary" type="submit">${UI.icon('check')} حفظ الأهداف</button></div></form>` });
    else if (st.tab === 'lookups') { const L = LOOKUPS[st.lookup], rows = Data.list(st.lookup); body = html`<div class="tabs">${Object.entries(LOOKUPS).map(([k, x]) => html`<button class="tab ${st.lookup === k ? 'active' : ''}" data-lookup="${k}">${UI.icon(x.icon)}${x.title}<span class="count">${fmtNum(Data.c[k].size)}</span></button>`)}</div>${UI.panel({ title: L.title, icon: L.icon, tools: html`<button class="btn btn-primary btn-sm" data-add>${UI.icon('plus')} إضافة</button>`, flush: true, body: rows.length ? html`<div class="table-wrap"><table class="table"><thead><tr><th>${L.illu ? 'الرسمة' : '#'}</th><th>الاسم</th>${L.fields.map((f) => html`<th>${f.label}</th>`)}<th>الترتيب</th><th></th></tr></thead><tbody class="stagger">${rows.map((r, i) => html`<tr><td>${L.illu ? UI.illu(r.illustration || 'box', 'mini') : i + 1}</td><td><b>${r.name}</b></td>${L.fields.map((f) => html`<td>${r[f.name] || '—'}</td>`)}<td>${fmtNum(r.order || 0)}</td><td class="nowrap"><button class="btn btn-ghost btn-sm" data-edit="${r.id}">${UI.icon('edit')}</button><button class="btn btn-ghost btn-sm" data-del="${r.id}">${UI.icon('trash')}</button></td></tr>`)}</tbody></table></div>` : html`<div class="panel-body">${UI.noData('لا توجد عناصر')}</div>` })}`; }
    else if (st.tab === 'templates') { const rows = await DB.getAll('templates'); body = UI.panel({ title: 'الردود الجاهزة للفنيين', icon: 'send', tools: html`<button class="btn btn-primary btn-sm" data-tpl-add>${UI.icon('plus')} رد جديد</button>`, body: rows.length ? html`<div class="grid g-2">${rows.map((r) => html`<div class="kb-card" style="cursor:default"><div class="row" style="justify-content:space-between"><b>${r.name}</b><span><button class="btn btn-ghost btn-sm" data-tpl-edit="${r.id}">${UI.icon('edit')}</button><button class="btn btn-ghost btn-sm" data-tpl-del="${r.id}">${UI.icon('trash')}</button></span></div><p>${r.body}</p></div>`)}</div>` : UI.noData('لا توجد ردود جاهزة') }); }
    else {
      const counts = await Promise.all(Object.keys(DB.SCHEMA).map(async (k) => [k, await DB.count(k)])), mig = await DB.get('meta', 'migration:legacy');
      const names = { users: 'المستخدمون', tickets: 'البلاغات', ticketEvents: 'أحداث البلاغات', attachments: 'المرفقات', items: 'الأصناف', stock: 'أرصدة المخازن', movements: 'الحركات', loans: 'العهد', kb: 'مقالات المعرفة', notifications: 'الإشعارات', activity: 'سجل النشاط', departments: 'الأقسام', categories: 'فئات البلاغات', itemCategories: 'تصنيفات الأصناف', warehouses: 'المخازن', ranks: 'الرتب', printers: 'الطابعات', templates: 'الردود', sessions: 'الجلسات', meta: 'إعدادات داخلية' };
      body = html`<div class="grid g-3">
        ${UI.panel({ tools: html`<a class="btn btn-ghost btn-sm" href="#/backup">${UI.icon('database')} مركز النسخ</a>`, title: 'نسخة احتياطية', icon: 'download', body: html`<p class="muted">نزّل نسخة كاملة من قاعدة البيانات بما فيها المرفقات في ملف واحد.</p><button class="btn btn-primary btn-block mt" data-act="backup">${UI.icon('download')} تنزيل النسخة الاحتياطية</button>` })}
        ${UI.panel({ title: 'استعادة نسخة', icon: 'upload', body: html`<p class="muted">استبدل كل البيانات الحالية بمحتوى ملف نسخة احتياطية سابقة.</p><button class="btn btn-danger btn-block mt" data-act="restore">${UI.icon('upload')} استعادة من ملف</button>` })}
        ${UI.panel({ title: 'عهد الإدارات', icon: 'building', body: html`<p class="muted">أعد بناء أرصدة عهد الإدارات من سجل حركات الصرف والإرجاع، إذا كانت لديك حركات قديمة قبل تفعيل تتبع العهد.</p><button class="btn btn-soft btn-block mt" data-act="rebuilddept">${UI.icon('refresh')} إعادة بناء عهد الإدارات</button>` })}
        ${UI.panel({ title: 'بيانات تجريبية', icon: 'layers', body: html`<p class="muted">أضف بلاغات وأصنافاً وحركات تجريبية لاستعراض الرسوم والتقارير.</p><button class="btn btn-soft btn-block mt" data-act="sample">${UI.icon('plus')} إضافة بيانات تجريبية</button><button class="btn btn-ghost btn-block" data-act="unsample" style="margin-top:8px">${UI.icon('trash')} حذف البيانات التجريبية</button>` })}
        ${Auth.user && Auth.user.role === 'supervisor' ? UI.panel({ title: 'تنظيف بيانات التجربة', icon: 'trash', body: html`<p class="muted">قبل التشغيل الرسمي: احذف البلاغات والمخزون والإشعارات وكل ما أُدخل أثناء التجربة، من الخادم ومن كل الأجهزة، مع الإبقاء على الإعدادات والقوائم والحسابات.</p><button class="btn btn-danger btn-block mt" data-act="wipetrial">${UI.icon('trash')} تنظيف بيانات التجربة</button>` }) : ''}
      </div>
      <div class="grid g-main mt">
        ${UI.panel({ title: 'محتوى قاعدة البيانات', icon: 'database', sub: 'قاعدة بيانات IndexedDB محلية في هذا المتصفح', body: UI.chart.hbars(counts.filter(([k]) => names[k]).sort((a, b) => b[1] - a[1]).map(([k, v], i) => ({ label: names[k], value: v, tone: TONES[i % TONES.length] }))) })}
        ${UI.panel({ title: 'ترحيل النظام السابق', icon: 'swap', body: mig && mig.value.found ? html`<div class="banner tone-teal">${UI.icon('check')}<div class="grow"><b>تم الترحيل في ${fmtDateTime(mig.value.at)}</b></div></div><dl class="kv">${Object.entries(mig.value.counts || {}).map(([k, v]) => html`<dt>${names[k] || k}</dt><dd>${fmtNum(v)}</dd>`)}</dl>` : UI.noData('لم تُعثر على بيانات من النظام السابق في هذا المتصفح') })}
      </div>`;
    }
    if (!ctx.alive()) return;
    ctx.view.innerHTML = String(html`${UI.pageHead({ title: 'الإعدادات والبيانات', sub: 'تحكم كامل في النظام وقوائمه وبياناته', illu: 'ups' })}<div class="tabs">${tabs.map(([k, l, ic]) => html`<button class="tab ${st.tab === k ? 'active' : ''}" data-tab="${k}">${UI.icon(ic)}${l}</button>`)}</div>${body}`);
    UI.hydrate(ctx.view);
    const g = $('#gForm', ctx.view); if (g) g.addEventListener('submit', async (e) => { e.preventDefault(); const { autoOn, autoStrategy, escalateAfter, autoCloseOn, autoCloseDays, avatars, ...rest } = UI.formValues(g); await Data.saveSettings({ ...rest, sessionHours: clamp(Number(rest.sessionHours) || 12, 1, 72), escalateAfter: clamp(Number(escalateAfter) || 60, 5, 1440), autoClose: Number(autoCloseOn) ? 1 : 0, autoCloseDays: clamp(Number(autoCloseDays) || 3, 1, 30), avatars: avatars || 'off', autoAssign: { on: Number(autoOn) ? 1 : 0, strategy: autoStrategy || 'least' } }); UI.toast('تم حفظ الإعدادات'); });
    const sf = $('#slaForm', ctx.view); if (sf) sf.addEventListener('submit', async (e) => { e.preventDefault(); const v = UI.formValues(sf), sla = {}; for (const k of Object.keys(PRIORITY)) { const r = Math.round(Number(v[`${k}_respond`])), h = Number(v[`${k}_resolve`]); if (!(r > 0) || !(h > 0)) { UI.toast('أدخل قيماً صحيحة أكبر من صفر', 'warn'); return; } sla[k] = { respond: r, resolve: Math.round(h * 60) }; } await Data.saveSettings({ sla }); UI.toast('تم حفظ أهداف الخدمة'); draw(); });
  };
  UI.on(ctx.view, 'click', '[data-tab]', (e, el) => { st.tab = el.dataset.tab; history.replaceState(null, '', `#/settings?tab=${st.tab}`); draw(); });
  UI.on(ctx.view, 'click', '[data-lookup]', (e, el) => { st.lookup = el.dataset.lookup; draw(); });
  UI.on(ctx.view, 'click', '[data-add]', async () => { if (await Pages.lookupModal(st.lookup)) draw(); });
  UI.on(ctx.view, 'click', '[data-edit]', async (e, el) => { if (await Pages.lookupModal(st.lookup, el.dataset.edit)) draw(); });
  UI.on(ctx.view, 'click', '[data-del]', async (e, el) => { const r = Data.c[st.lookup].get(el.dataset.del); if (await UI.confirm(`حذف «${r.name}»؟`, { danger: true, ok: 'حذف' })) { try { await Data.deleteRecord(st.lookup, r.id, LOOKUPS[st.lookup].title); UI.toast('تم الحذف'); draw(); } catch (ex) { UI.error(ex); } } });
  const tplModal = async (id) => { const r = id ? await DB.get('templates', id) : {}; return UI.modal({ title: id ? 'تعديل الرد' : 'رد جاهز جديد', icon: 'send', body: UI.fields([{ name: 'name', label: 'اسم الرد', required: true, wide: true }, { name: 'body', label: 'نص الرد', type: 'textarea', rows: 5, wide: true }], r), actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'حفظ', kind: 'primary', submit: true, handler: async (form) => { const v = UI.formValues(form); if (!v.name.trim() || !v.body.trim()) throw new AppError('الاسم والنص مطلوبان'); return Data.saveRecord('templates', { ...r, ...v }, 'رد جاهز'); } }] }); };
  UI.on(ctx.view, 'click', '[data-tpl-add]', async () => { if (await tplModal()) draw(); });
  UI.on(ctx.view, 'click', '[data-tpl-edit]', async (e, el) => { if (await tplModal(el.dataset.tplEdit)) draw(); });
  UI.on(ctx.view, 'click', '[data-tpl-del]', async (e, el) => { if (await UI.confirm('حذف هذا الرد الجاهز؟', { danger: true, ok: 'حذف' })) { await Data.deleteRecord('templates', el.dataset.tplDel, 'رد جاهز'); draw(); } });
  UI.on(ctx.view, 'click', '[data-act="backup"]', async (e, btn) => { UI.busy(btn, true); try { const data = await DB.exportAll(); downloadBlob(new Blob([JSON.stringify(data)], { type: 'application/json' }), `نسخة-احتياطية-${dateInput(now())}.json`); await Data.log('backup', 'system', '', 'تنزيل نسخة احتياطية'); UI.toast('تم تنزيل النسخة الاحتياطية'); } catch (ex) { UI.error(ex); } finally { UI.busy(btn, false); } });
  UI.on(ctx.view, 'click', '[data-act="restore"]', async () => { if (!(await UI.confirm('ستُستبدل كل البيانات الحالية بمحتوى الملف. يُنصح بتنزيل نسخة احتياطية أولاً. هل تريد المتابعة؟', { danger: true, ok: 'اختيار الملف' }))) return; const [file] = await UI.pickFiles({ accept: '.json,application/json', multiple: false }); if (!file) return; try { await DB.importAll(JSON.parse(await readText(file))); UI.toast('تمت الاستعادة، سيُعاد تحميل النظام'); setTimeout(() => location.reload(), 1200); } catch (ex) { UI.error(ex instanceof AppError ? ex : new AppError('الملف غير صالح أو تالف')); } });
  UI.on(ctx.view, 'click', '[data-act="sample"]', async () => {
    const r = await UI.modal({ title: 'إضافة بيانات تجريبية', icon: 'layers', size: 'sm', body: UI.fields([{ name: 'tickets', label: 'عدد البلاغات', type: 'number', min: 10, max: 20000, value: 400, wide: true }, { name: 'items', label: 'عدد الأصناف', type: 'number', min: 0, max: 5000, value: 60, wide: true }]), actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'إضافة', kind: 'primary', icon: 'plus', submit: true, handler: async (form) => { const v = UI.formValues(form); await Data.sample.load({ tickets: clamp(Number(v.tickets) || 0, 0, 20000), items: clamp(Number(v.items) || 0, 0, 5000) }); return true; } }] });
    if (r) { UI.toast('تمت إضافة البيانات التجريبية'); UI.confetti(); Bus.emit('tickets', {}); Bus.emit('inventory', {}); draw(); }
  });
  UI.on(ctx.view, 'click', '[data-act="unsample"]', async (e, btn) => { if (!(await UI.confirm('ستُحذف البلاغات والأصناف والحركات والعهد والحسابات التجريبية فقط، ولن تتأثر بياناتك الحقيقية. هل تريد المتابعة؟', { danger: true, ok: 'حذف البيانات التجريبية' }))) return; UI.busy(btn, true); try { const n = await Data.sample.clear(); UI.toast(`حُذف ${arCount(n.tickets, AR.ticket)} و${arCount(n.items, AR.item)} من البيانات التجريبية`); draw(); } catch (ex) { UI.error(ex); } finally { UI.busy(btn, false); } });
  UI.on(ctx.view, 'click', '[data-act="rebuilddept"]', async (e, btn) => { UI.busy(btn, true); try { const r = await Data.dept.rebuild(); UI.toast(`أُعيد بناء عهد الإدارات: ${fmtNum(r.rows)} سجل بإجمالي ${fmtNum(r.units)} وحدة`); draw(); } catch (ex) { UI.error(ex); } finally { UI.busy(btn, false); } });
  UI.on(ctx.view, 'click', '[data-act="unsample"]', async (e, btn) => { if (!(await UI.confirm('ستُحذف البلاغات والأصناف والحركات والعهد والحسابات التجريبية فقط، ولن تتأثر بياناتك الحقيقية. هل تريد المتابعة؟', { danger: true, ok: 'حذف البيانات التجريبية' }))) return; UI.busy(btn, true); try { const n = await Data.sample.clear(); UI.toast(`حُذف ${arCount(n.tickets, AR.ticket)} و${arCount(n.items, AR.item)} من البيانات التجريبية`); draw(); } catch (ex) { UI.error(ex); } finally { UI.busy(btn, false); } });
  await draw();
};

/* ── النماذج والاستمارات ───────────────────────────────────── */

/* ── التشغيل ───────────────────────────────────────────────── */
async function boot() {
  UI.theme.apply();
  document.body.insertAdjacentHTML('afterbegin', SPRITE + '<div class="app-bg" aria-hidden="true"><i></i><i></i><i></i></div>');
  try { await DB.open(); await Sync.init(); if (Sync.on) await Sync.pull(Sync.needFull()); await Migration.run(); if (!(Sync.on && !Sync.serverEmpty)) await Seed.ensure(); await Data.refresh(); await renameOrgDefaults(); await Auth.restore(); }
  catch (e) {
    console.error(e);
    const bb = $('#boot'); if (bb) bb.remove();
    const proto = location.protocol, isFile = proto === 'file:';
    const why = isFile
      ? 'أنت تفتح النظام من ملف مباشر أو مجلد مشترك (file://)، والمتصفح يمنع التخزين في هذه الحالة. ضع الملف في مجلد الخادم htdocs وافتحه بعنوان مثل http://اسم-الخادم/it/'
      : e instanceof AppError ? e.message
        : 'التخزين محجوب في هذا المتصفح: قد يكون وضع التصفح الخاص، أو سياسة الجهاز تمنع «بيانات المواقع». افتح النظام في Chrome أو Edge بوضع عادي، واسمح ببيانات المواقع لهذا العنوان.';
    window.__sqBooted = true; clearTimeout(window.__sqWatch);
    const ua = navigator.userAgent, br = (ua.match(/Edg\/[\d.]+/) || ua.match(/Chrome\/[\d.]+/) || ua.match(/Firefox\/[\d.]+/) || ua.match(/Version\/[\d.]+ Safari/) || [''])[0];
    $('#app').innerHTML = String(UI.empty({ illu: 'drive', title: 'تعذر تشغيل النظام على هذا المتصفح', text: why, action: html`<div class="boot-diag"><div>العنوان الحالي: <b class="ltr">${String(location.href).slice(0, 110)}</b></div><div>طريقة الفتح: <b class="ltr">${proto}</b>${isFile ? html` <span class="chip tone-red"><i class="dot"></i>غير مدعومة</span>` : ''}</div><div>المتصفح: <b class="ltr">${br}</b></div><div>تفاصيل الخطأ: <b class="ltr">${String((e && e.name) || '')}: ${String((e && e.message) || e).slice(0, 160)}</b></div><div class="row mt" style="gap:8px;justify-content:center"><button type="button" class="btn btn-primary" data-act="reload">${UI.icon('refresh')} إعادة المحاولة</button><button type="button" class="btn" data-act="repair">${UI.icon('trash')} إصلاح بيانات المتصفح</button></div><p class="hint mt">«إصلاح بيانات المتصفح» يحذف النسخة المحلية فقط، وبياناتك محفوظة على الخادم.</p></div>` }));
    const rb = document.querySelector('[data-act="reload"]'); if (rb) rb.onclick = () => location.reload();
    const fb = document.querySelector('[data-act="repair"]'); if (fb) fb.onclick = () => window.__sqRepair();
    return;
  }
  const R = (p, perm, fn, t, bare) => Router.add(p, perm, fn, t, bare);
  R('/dashboard', 'dashboard', Pages.dashboard, 'لوحة القيادة'); R('/tickets', 'tickets.view', Pages.tickets, 'البلاغات'); R('/tickets/new', 'tickets.create', Pages.newTicket, 'بلاغ جديد'); R('/tickets/:id', 'tickets.view', Pages.ticket, 'تفاصيل البلاغ');
  R('/inventory', 'inventory.read', Pages.inventory, 'المخازن'); R('/inventory/items', 'inventory.read', Pages.items, 'الأصناف'); R('/inventory/items/:id', 'inventory.read', Pages.item, 'تفاصيل الصنف'); R('/inventory/movements', 'inventory.read', Pages.movements, 'حركات المخزون'); R('/inventory/loans', 'inventory.read', Pages.loans, 'العهد'); R('/inventory/departments', 'inventory.read|custody.direct', Pages.deptStock, 'عهدة الإدارات'); R('/inventory/departments/:id', 'inventory.read|custody.direct', Pages.deptDetail, 'عهدة إدارة'); R('/inventory/report', 'inventory.read', Pages.invReport, 'تقرير المخزون'); R('/inventory/browse', 'inventory.read', Pages.browse, 'تصفح المخزن'); R('/inventory/search', 'inventory.read', Pages.invSearch, 'البحث في المخزن'); R('/chat', '', Pages.chat, 'الاستفسارات'); R('/forms', '', Pages.formsPage, 'النماذج والاستمارات'); R('/backup', 'backup.manage', Pages.backup, 'النسخ الاحتياطي'); R('/status', '', Pages.status, 'حالة الخدمات'); R('/worklog', 'worklog', Pages.worklog, 'أعمال القسم'); R('/works', 'works', Pages.works, 'متابعة الأعمال'); R('/passwords', 'users.password', Pages.passwords, 'كلمات المرور'); R('/chat/report', 'reports', Pages.chatReport, 'تقرير الاستفسارات'); R('/chat/:id', '', Pages.chat, 'الاستفسارات'); R('/inventory/vouchers', 'inventory.read', Pages.vouchers, 'سندات الصرف'); R('/maintenance', 'inventory.read', Pages.maintenance, 'الصيانة'); R('/inventory/retired', 'inventory.read', Pages.retired, 'الخارج عن الخدمة');
  R('/kb', 'kb.read', Pages.kb, 'قاعدة المعرفة'); R('/org', 'org.manage', Pages.org, 'الهيكل التنظيمي'); R('/reports', 'reports', Pages.reports, 'التقارير'); R('/users', 'users.manage', Pages.users, 'المستخدمون'); R('/activity', 'activity', Pages.activity, 'سجل النشاط'); R('/settings', 'settings', Pages.settings, 'الإعدادات');
  R('/notifications', null, Pages.notifications, 'الإشعارات'); R('/profile', null, Pages.profile, 'الملف الشخصي'); R('/welcome', null, Pages.welcome, 'أكمل بياناتك', true); R('/monitor', null, Pages.monitor, 'شاشة المراقبة', true);
  window.addEventListener('hashchange', () => Router.resolve());
  document.addEventListener('keydown', (e) => { if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k' && Auth.user && Auth.user.role !== 'monitor') { e.preventDefault(); UI.palette(); } });
  matchMedia('(prefers-color-scheme: light)').addEventListener('change', () => { if (!localStorage.getItem('sq_theme')) UI.theme.apply(); });
  ['departments', 'categories', 'warehouses', 'itemCategories', 'printers', 'ranks', 'users'].forEach((k) => Bus.on(k === 'users' ? 'users' : `data:${k}`, (e) => { if (e.detail && e.detail.remote && !e.detail.synced) Data.refresh(k); }));
  Bus.on('settings', (e) => { if (e.detail && e.detail.remote) Data.refresh('settings'); });
  setInterval(async () => { if (Auth.user && Sync.on && Sync.token) { try { await Sync.call('me', { timeout: 8000 }); return; } catch (e) { if (!e || e.status !== 401) return; } } if (Auth.user && !(await Auth.restore())) { UI.toast('انتهت الجلسة، يرجى تسجيل الدخول مجدداً', 'warn'); Shell.unmount(); Router.resolve(); } }, 60000);
  window.addEventListener('unhandledrejection', (e) => { if (e.reason instanceof AppError) { UI.toast(e.reason.message, 'error'); e.preventDefault(); } });
  window.App = { DB, Data, Auth, Router, UI, Crypto, Pages, Stats, Medals, XL, Forms, Spec, Escalate, AutoClose, Cart, Sync, ChatAutoClose, Presence, Custody, Handover, AnnTpl, Nav, NoteSweep, Surveys, Ratings, Engage, PrintCat, PP };
  const b = $('#boot'); if (b) b.remove();
  window.__sqBooted = true; clearTimeout(window.__sqWatch); const slow = $('#bootSlow'); if (slow) slow.remove();
  await Router.resolve();
  if (DB.memory || window.__sqNoStore) setTimeout(() => UI.toast(Sync.on ? 'هذا المتصفح يمنع حفظ بيانات المواقع، فيعمل النظام بوضع مؤقت ويعيد تحميل البيانات عند كل فتح. للحل الدائم: اسمح بحفظ البيانات لهذا العنوان من إعدادات المتصفح (ملفات تعريف الارتباط وبيانات المواقع).' : 'هذا المتصفح يمنع حفظ البيانات ولا يوجد اتصال بالخادم: أي تعديل سيضيع عند إغلاق الصفحة.', 'warn', 15000), 1500);
  else if (DB.repaired) setTimeout(() => UI.toast('أُصلحت قاعدة البيانات المحلية لهذا المتصفح وأُعيد تحميل البيانات من الخادم', 'info', 8000), 1500);
}

/* ── إضافات: عدّ عربي سليم، تحديث حي للوحات، بيانات تجريبية واقعية ── */
const arCount = (n, forms) => {
  const v = Math.round(Number(n) || 0), f = fmtNum(v), r = v % 100, [one, two, few, many, hundred] = forms;
  if (v === 0) return `${f} ${few}`;
  if (v === 1) return one;
  if (v === 2) return two;
  if (r >= 3 && r <= 10) return `${f} ${few}`;
  if (r >= 11 && r <= 99) return `${f} ${many}`;
  return `${f} ${hundred || many}`;
};
const AR = {
  ticket: ['بلاغ واحد', 'بلاغان', 'بلاغات', 'بلاغاً', 'بلاغ'],
  openTicket: ['بلاغ مفتوح واحد', 'بلاغان مفتوحان', 'بلاغات مفتوحة', 'بلاغاً مفتوحاً', 'بلاغ مفتوح'],
  article: ['مقال واحد', 'مقالان', 'مقالات', 'مقالاً', 'مقال'],
  item: ['صنف واحد', 'صنفان', 'أصناف', 'صنفاً', 'صنف'],
  tech: ['فني واحد', 'فنيين اثنين', 'فنيين', 'فنياً', 'فني']
};

/* تحديث هادئ للوحة القيادة عند تغيّر البيانات دون إعادة الحركات أو فقدان موضع التمرير */
Pages.live = async (ctx, draw, boardOpts) => {
  await draw(); if (!ctx.alive()) return;
  Pages.bindCommon(ctx);
  let dirty = false, busy = false;
  const mark = () => { dirty = true; };
  ctx.onCleanup(Bus.on('tickets', mark)); ctx.onCleanup(Bus.on('inventory', mark));
  if (boardOpts) ctx.onCleanup(Bus.on('tickets', debounce(() => { const el = $('#board', ctx.view); if (ctx.alive() && el) Board.render(el, boardOpts); }, 500)));
  const tick = setInterval(async () => {
    if (!dirty || busy || !ctx.alive() || document.hidden || $('dialog[open]') || $('.cmdk') || now() - (Pages.lastMove || 0) < 4000) return;
    busy = true; dirty = false; const y = window.scrollY;
    ctx.view.classList.remove('page-in'); ctx.view.classList.add('quiet');
    try { await draw(); if (ctx.alive()) { UI.hydrate(ctx.view); window.scrollTo(0, y); } } catch (e) { console.warn('live refresh', e); }
    busy = false;
  }, 25000);
  ctx.onCleanup(() => clearInterval(tick));
};
document.addEventListener('pointermove', () => { Pages.lastMove = now(); }, { passive: true });

/* ── مولّد بيانات تجريبية واقعية ── */
