AR.user = ['مستخدم واحد', 'مستخدمين اثنين', 'مستخدمين', 'مستخدماً', 'مستخدم'];
const latinDigits = (s) => String(s == null ? '' : s).replace(/[٠-٩]/g, (d) => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g, (d) => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
const headKey = (h) => normalizeAr(h).replace(/[\s_\-.:()/\\]/g, '');
const IMPORT_COLS = { name: ['الاسم', 'الاسمالكامل', 'اسمالموظف', 'الاسمالرباعي', 'name', 'fullname'], militaryNo: ['الرقمالعسكري', 'رقمعسكري', 'الرقم', 'militaryno', 'militarynumber', 'serviceno'], role: ['الدور', 'الصلاحيه', 'نوعالحساب', 'role'], department: ['الاداره', 'القسم', 'الادارهالقسم', 'department'], location: ['المبني', 'الموقع', 'المبنيالموقع', 'building', 'location'], office: ['المكتب', 'الغرفه', 'office'], phone: ['الهاتف', 'رقمالهاتف', 'الجوال', 'phone', 'mobile'], rank: ['الرتبه', 'rank'] };
const ROLE_NORM = new Map(Object.entries({ 'موظف': 'department', 'موظفه': 'department', 'مستخدم': 'department', 'فني': 'technician', 'فنيه': 'technician', 'اداري': 'support_manager', 'اداريه': 'support_manager', 'مشرف': 'supervisor', 'مشرفه': 'supervisor', 'شاشهمراقبه': 'monitor', 'شاشه': 'monitor', employee: 'department', user: 'department', technician: 'technician', tech: 'technician', admin: 'support_manager', administrator: 'support_manager', manager: 'support_manager', supervisor: 'supervisor', monitor: 'monitor' }));
const headerMap = (row) => { const m = {}; (row || []).forEach((h, i) => { const k = headKey(h); for (const [f, names] of Object.entries(IMPORT_COLS)) if (m[f] == null && names.includes(k)) m[f] = i; }); return m; };

Pages.analyzeImport = (sheets, fileName) => {
  let sheet = null, hi = -1, map = null;
  for (const s of sheets) { for (let r = 0; r < Math.min(10, s.rows.length); r++) { const m = headerMap(s.rows[r]); if (m.name != null && m.militaryNo != null) { sheet = s; hi = r; map = m; break; } } if (sheet) break; }
  if (!sheet) throw new AppError('لم أجد عمودي «الاسم» و«الرقم العسكري» في الملف. نزّل القالب الجاهز واستخدمه.');
  const users = Data.list('users'), byMil = new Map(users.filter((u) => u.militaryNo).map((u) => [latinDigits(u.militaryNo).toLowerCase(), u]));
  const depBy = new Set(Data.list('departments').map((d) => normalizeAr(d.name))), locBy = new Set(Data.list('locations').map((l) => normalizeAr(l.name)));
  const sup = Auth.user.role === 'supervisor', seen = new Set(), rows = [], newDeps = new Map(), newLocs = new Map();
  sheet.rows.slice(hi + 1).forEach((r, i) => {
    const cell = (k) => (map[k] != null ? String(r[map[k]] || '').replace(/\s+/g, ' ').trim() : '');
    const name = cell('name'), mil = latinDigits(cell('militaryNo')).replace(/\s+/g, ''), roleRaw = cell('role');
    if (!name && !mil && !roleRaw) return;
    const role = roleRaw ? ROLE_NORM.get(headKey(roleRaw)) : 'department';
    const row = { line: hi + i + 2, name, militaryNo: mil, roleRaw, role, department: cell('department'), location: cell('location'), office: cell('office'), phone: latinDigits(cell('phone')), rank: cell('rank'), issues: [], note: '' };
    if (name.length < 3) row.issues.push('الاسم ناقص');
    if (!mil) row.issues.push('الرقم العسكري مفقود'); else if (!/^[\p{L}\p{N}-]{2,20}$/u.test(mil)) row.issues.push('رقم عسكري غير صالح');
    if (!role) row.issues.push(`دور غير معروف «${roleRaw}»`); else if (!sup && ['supervisor', 'support_manager'].includes(role)) row.issues.push('إضافة المشرف والإداري من صلاحية المشرف فقط');
    const key = mil.toLowerCase(); if (mil && seen.has(key)) row.issues.push('رقم عسكري مكرر في الملف'); if (mil) seen.add(key);
    row.existing = byMil.get(key) || null;
    if (row.existing && row.existing.id === Auth.user.id && role !== Auth.user.role) row.note = 'حسابك الحالي: لن يتغير دورك';
    if (!roleRaw && !row.issues.length) row.note = 'بلا دور: سيُسجَّل موظفاً';
    if (!row.issues.length) { if (row.department && !depBy.has(normalizeAr(row.department))) newDeps.set(normalizeAr(row.department), row.department); if (row.location && !locBy.has(normalizeAr(row.location))) newLocs.set(normalizeAr(row.location), row.location); }
    row.status = row.issues.length ? 'error' : row.existing ? 'update' : 'new';
    rows.push(row);
  });
  if (!rows.length) throw new AppError('الملف لا يحتوي على بيانات مستخدمين تحت صف العناوين');
  return { fileName, sheet: sheet.name, rows, newDeps: [...newDeps.values()], newLocs: [...newLocs.values()] };
};

Pages.runImport = async (a, { mode = 'random', update = true } = {}, onProgress) => {
  const t = now(), me = Auth.user, ok = a.rows.filter((r) => r.status === 'new' || (r.status === 'update' && update));
  const addLookups = async (store, names) => { if (!names.length) return; const base = await DB.count(store); await DB.bulkPut(store, names.map((name, i) => ({ id: uid(store === 'departments' ? 'dep' : 'loc'), name, description: '', order: base + i, createdAt: t, updatedAt: t }))); await Data.refresh(store); };
  const usedDeps = new Set(ok.map((r) => normalizeAr(r.department))), usedLocs = new Set(ok.map((r) => normalizeAr(r.location)));
  await addLookups('departments', a.newDeps.filter((n) => usedDeps.has(normalizeAr(n)))); await addLookups('locations', a.newLocs.filter((n) => usedLocs.has(normalizeAr(n))));
  const idOf = (store) => new Map(Data.list(store).map((x) => [normalizeAr(x.name), x.id])), depBy = idOf('departments'), locBy = idOf('locations'), rankBy = idOf('ranks');
  const taken = new Set(Data.list('users').map((u) => u.username)), creds = [], batch = []; let created = 0, updated = 0;
  for (let i = 0; i < ok.length; i++) {
    const r = ok[i], depId = r.department ? depBy.get(normalizeAr(r.department)) || '' : '', locId = r.location ? locBy.get(normalizeAr(r.location)) || '' : '', rankId = r.rank ? rankBy.get(normalizeAr(r.rank)) || '' : '';
    if (r.existing) {
      const u = await DB.get('users', r.existing.id);
      if (u) { u.name = r.name; if (u.id !== me.id) u.role = r.role; if (depId) u.departmentId = depId; if (locId) u.locationId = locId; if (r.office) u.office = r.office; if (r.phone) u.phone = r.phone; if (rankId) u.rankId = rankId; u.militaryNo = r.militaryNo; u.updatedAt = t; batch.push(u); updated += 1; }
    } else {
      let username = r.militaryNo.toLowerCase(); if (username.length < 3) username = `u${username}`; while (taken.has(username)) username = `${username}_1`; taken.add(username);
      const pw = mode === 'military' ? r.militaryNo : Crypto.tempPassword(), salt = Crypto.randomHex(16);
      const pass = mode === 'military' ? { algo: 'legacy', kind: 'plain', value: r.militaryNo } : { algo: 'pbkdf2-sha256', iter: 1000, salt, hash: Crypto.hex(Crypto.pbkdf2(pw, Crypto.unhex(salt), 1000)) };
      batch.push({ id: uid('u'), username, name: r.name, role: r.role, departmentId: depId, locationId: locId, office: r.office || '', rankId, militaryNo: r.militaryNo, phone: r.phone || '', email: '', active: 1, mustChangePassword: 0, pass, extraPerms: [], deniedPerms: [], createdAt: t, updatedAt: t, lastLoginAt: 0, imported: 1 });
      creds.push([r.name, r.militaryNo, username, pw, ROLES[r.role], Data.nameOf('departments', depId, ''), Data.nameOf('locations', locId, '')]); created += 1;
    }
    if (batch.length >= 150 || i === ok.length - 1) { await DB.bulkPut('users', batch.splice(0)); if (onProgress) onProgress(i + 1, ok.length); await new Promise((res) => setTimeout(res, 0)); }
  }
  await Data.refresh('users');
  await Data.log('import', 'user', '', `استيراد من Excel (${a.fileName}): ${created} جديد، ${updated} تحديث`); Bus.emit('users');
  return { created, updated, skipped: a.rows.length - ok.length, creds, mode };
};

Pages.usersTemplate = () => {
  const deps = Data.list('departments').map((d) => d.name), locs = Data.list('locations').map((l) => l.name), ranks = Data.list('ranks').map((r) => r.name), n = Math.max(deps.length, locs.length, ranks.length, 1);
  const lists = [['الإدارات', 'المباني', 'الرتب'], ...Array.from({ length: n }, (_, i) => [deps[i] || '', locs[i] || '', ranks[i] || ''])];
  const blob = XL.write([
    { name: 'المستخدمون', widths: [32, 16, 12, 28, 26, 22, 16, 16], rows: [['الاسم', 'الرقم العسكري', 'الدور', 'الإدارة', 'المبنى', 'المكتب', 'الهاتف', 'الرتبة'], ['أحمد بن سالم الحارثي', '123456', 'موظف', deps[0] || 'المالية', locs[1] || '', 'مكتب 214', '99123456', ranks[0] || ''], ['سالم بن خميس البلوشي', '234567', 'فني', deps.find((d) => /تقنية/.test(d)) || deps[0] || '', '', '', '', ''], ['مريم بنت سعيد الكندية', '345678', 'إداري', deps.find((d) => /تقنية/.test(d)) || deps[0] || '', '', '', '', '']],
      validations: [{ sqref: 'C2:C10000', formula: '"موظف,فني,إداري,مشرف"', strict: true }, { sqref: 'D2:D10000', formula: `'القوائم'!$A$2:$A$${n + 1}` }, { sqref: 'E2:E10000', formula: `'القوائم'!$B$2:$B$${n + 1}` }, { sqref: 'H2:H10000', formula: `'القوائم'!$C$2:$C$${n + 1}` }] },
    { name: 'القوائم', widths: [34, 30, 22], rows: lists },
    { name: 'تعليمات', header: false, widths: [110], rows: [['تعليمات استيراد المستخدمين'], ['1. الأعمدة المطلوبة: الاسم، الرقم العسكري، الدور. بقية الأعمدة اختيارية.'], ['2. قيم الدور: موظف، فني، إداري، مشرف. الصف الذي يُترك دوره فارغاً يُسجَّل موظفاً.'], ['3. اسم الدخول لكل مستخدم هو رقمه العسكري.'], ['4. الإدارات والمباني غير الموجودة في النظام تُضاف تلقائياً.'], ['5. إذا وُجد مستخدم بنفس الرقم العسكري تُحدَّث بياناته ولا تتغير كلمة مروره.'], ['6. من لم يُحدد مبناه يختاره بنفسه عند أول دخول، ويُطلب من الجميع تغيير كلمة المرور الأولية.']] }
  ]);
  downloadBlob(blob, 'قالب-استيراد-المستخدمين.xlsx');
};

Pages.exportUsers = () => {
  const rows = Data.list('users').map((u) => [u.name, u.militaryNo || '', u.username, ROLES[u.role] || u.role, Data.nameOf('departments', u.departmentId, ''), Data.nameOf('locations', u.locationId, ''), u.office || '', u.phone || '', Data.nameOf('ranks', u.rankId, ''), u.active ? 'مفعّل' : 'موقوف', u.lastLoginAt ? fmtDateTime(u.lastLoginAt) : '', (u.extraPerms || []).map((p) => PERM_LABEL[p]).join('، ')]);
  downloadBlob(XL.write([{ name: 'المستخدمون', widths: [32, 16, 16, 14, 28, 26, 22, 14, 16, 10, 20, 34], rows: [['الاسم', 'الرقم العسكري', 'اسم المستخدم', 'الدور', 'الإدارة', 'المبنى', 'المكتب', 'الهاتف', 'الرتبة', 'الحالة', 'آخر دخول', 'صلاحيات إضافية'], ...rows] }]), `المستخدمون-${dateInput(now())}.xlsx`);
  UI.toast(`تم تصدير ${arCount(rows.length, AR.user)} إلى Excel`);
};

Pages.importUsers = () => new Promise((resolve) => {
  let analysis = null, result = null, filter = 'all';
  const steps = (n) => html`<div class="imp-steps">${['جهّز الملف', 'راجع البيانات', 'تم الاستيراد'].map((l, i) => html`<div class="imp-step ${n === i + 1 ? 'on' : n > i + 1 ? 'done' : ''}"><i>${n > i + 1 ? UI.icon('check') : i + 1}</i>${l}</div>`)}</div>`;
  const pickView = () => html`${steps(1)}<div class="grid g-2"><div class="imp-card">${UI.illu('box')}<b>القالب الجاهز</b><p>الأعمدة المطلوبة: <b>الاسم</b>، <b>الرقم العسكري</b>، <b>الدور</b> (موظف، فني، إداري، مشرف). ويمكن إضافة: الإدارة، المبنى، المكتب، الهاتف، الرتبة.</p><button type="button" class="btn btn-soft" data-imp="template">${UI.icon('download')} تنزيل قالب Excel</button></div><div class="dropzone" data-imp="pick" tabindex="0" role="button">${UI.icon('upload')}<b>اسحب ملف Excel هنا أو انقر للاختيار</b><span class="small faint">xlsx أو csv — ملف واحد لكل الموظفين</span></div></div><div class="imp-rules"><div>${UI.icon('key')}<span>اسم الدخول لكل مستخدم هو <b>رقمه العسكري</b>، ويُلزم بتغيير كلمة المرور الأولية.</span></div><div>${UI.icon('building')}<span>الإدارات والمباني الجديدة في الملف <b>تُضاف تلقائياً</b> وتُربط بأصحابها.</span></div><div>${UI.icon('refresh')}<span>المستخدم الموجود (نفس الرقم العسكري) <b>تُحدَّث بياناته</b> دون تغيير كلمة مروره.</span></div><div>${UI.icon('pin')}<span>من لم يُحدد مبناه <b>يختاره بنفسه</b> عند أول دخول.</span></div></div>`;
  const reviewView = () => {
    const a = analysis, c = { new: 0, update: 0, error: 0 }; a.rows.forEach((r) => { c[r.status] += 1; });
    const roles = {}; a.rows.filter((r) => r.status !== 'error').forEach((r) => { roles[r.role] = (roles[r.role] || 0) + 1; });
    const shown = a.rows.filter((r) => filter === 'all' || r.status === filter), label = { new: ['teal', 'جديد'], update: ['sky', 'تحديث'], error: ['red', 'خطأ'] };
    return html`${steps(2)}<div class="imp-summary">${UI.chip('slate', `${a.fileName} — ${a.sheet}`, 'file')}${UI.chip('teal', `جديد: ${fmtNum(c.new)}`, 'user-plus')}${UI.chip('sky', `تحديث: ${fmtNum(c.update)}`, 'refresh')}${c.error ? UI.chip('red', `أخطاء: ${fmtNum(c.error)}`, 'alert') : ''}${Object.entries(roles).map(([k, n]) => UI.chip(ROLE_INFO[k] ? ROLE_INFO[k].tone : 'slate', `${ROLES[k]}: ${fmtNum(n)}`))}</div>
      ${a.newDeps.length ? html`<div class="banner tone-violet">${UI.icon('building')}<div class="grow"><b>إدارات جديدة ستُضاف تلقائياً (${fmtNum(a.newDeps.length)})</b><div class="small muted">${a.newDeps.join('، ')}</div></div></div>` : ''}
      ${a.newLocs.length ? html`<div class="banner tone-sky">${UI.icon('pin')}<div class="grow"><b>مبانٍ جديدة ستُضاف تلقائياً (${fmtNum(a.newLocs.length)})</b><div class="small muted">${a.newLocs.join('، ')}</div></div></div>` : ''}
      <div class="imp-options"><div class="field"><label>كلمة المرور الأولية</label><div class="seg"><label><input type="radio" name="pwmode" value="random" checked><span>${UI.icon('key')} عشوائية لكل مستخدم</span></label><label><input type="radio" name="pwmode" value="military"><span>${UI.icon('shield')} الرقم العسكري</span></label></div><small class="hint">في الحالتين يُطلب من المستخدم تعيين كلمة مرور خاصة عند أول دخول.</small></div>${UI.field({ name: 'update', type: 'switch', text: 'تحديث بيانات المستخدمين الموجودين' }, 1)}<div class="seg" style="margin-inline-start:auto">${[['all', 'الكل'], ['new', 'الجديد'], ['update', 'التحديث'], ['error', 'الأخطاء']].map(([k, l]) => html`<label><input type="radio" name="impfilter" value="${k}"${filter === k ? raw(' checked') : ''}><span>${l}</span></label>`)}</div></div>
      <div class="table-wrap imp-table"><table class="table"><thead><tr><th>السطر</th><th>الاسم</th><th>الرقم العسكري</th><th>الدور</th><th>الإدارة</th><th>المبنى</th><th>الحالة</th></tr></thead><tbody>${shown.slice(0, 400).map((r) => html`<tr class="${r.status === 'error' ? 'err' : ''}"><td class="t-num">${r.line}</td><td>${r.name || html`<span class="faint">—</span>`}</td><td><span class="ltr">${r.militaryNo || '—'}</span></td><td>${r.role ? UI.chip(ROLE_INFO[r.role].tone, ROLES[r.role]) : html`<span class="faint">${r.roleRaw}</span>`}</td><td class="small">${r.department || html`<span class="faint">—</span>`}</td><td class="small">${r.location || html`<span class="faint">يختاره عند الدخول</span>`}</td><td>${UI.chip(label[r.status][0], label[r.status][1])}${r.issues.length ? html`<div class="t-sub" style="color:rgb(var(--red-ink))">${r.issues.join('، ')}</div>` : r.note ? html`<div class="t-sub">${r.note}</div>` : ''}</td></tr>`)}</tbody></table></div>${shown.length > 400 ? html`<p class="hint mt">يُعرض أول 400 صف من ${fmtNum(shown.length)}.</p>` : ''}
      <div class="imp-progress" hidden><div class="progress"><i style="width:0%"></i></div><span>جارٍ الاستيراد...</span></div>
      <div class="row imp-actions"><button type="button" class="btn btn-ghost" data-imp="again">${UI.icon('upload')} اختيار ملف آخر</button><button type="button" class="btn btn-primary btn-lg" data-imp="run"${c.new + c.update ? '' : raw(' disabled')}>${UI.icon('check')} استيراد ${arCount(c.new + c.update, AR.user)}</button></div>`;
  };
  const doneView = () => html`${steps(3)}<div class="success" style="padding:20px 10px"><div class="burst"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.5 4.5L19 7.5" pathLength="1"/></svg></div><h2 style="font-size:23px">تم الاستيراد بنجاح</h2><div class="imp-summary" style="justify-content:center">${UI.chip('teal', `حسابات جديدة: ${fmtNum(result.created)}`, 'user-plus')}${UI.chip('sky', `حُدّثت: ${fmtNum(result.updated)}`, 'refresh')}${result.skipped ? UI.chip('slate', `تُخطيت: ${fmtNum(result.skipped)}`, 'x') : ''}</div>${result.created ? html`<p class="muted" style="max-width:560px">${result.mode === 'military' ? 'كلمة المرور الأولية لكل مستخدم هي رقمه العسكري.' : 'نزّل ملف كلمات المرور الأولية ووزّعه بطريقة آمنة ثم احذفه.'} يدخل كل مستخدم برقمه العسكري، ويُطلب منه تعيين كلمة مرور خاصة واختيار مبناه.</p><button type="button" class="btn btn-primary btn-lg" data-imp="creds">${UI.icon('download')} تنزيل ملف الحسابات (Excel)</button>` : ''}</div>`;
  UI.modal({
    title: 'استيراد المستخدمين من Excel', icon: 'upload', size: 'xl', body: html`<div id="impBox">${pickView()}</div>`, actions: [{ label: 'إغلاق', kind: 'ghost', value: null }],
    onMount: (form) => {
      const box = $('#impBox', form), render = (v) => { box.innerHTML = String(v); UI.hydrate(box); };
      const load = async (file) => {
        if (!file) return;
        try {
          const isCsv = /\.csv$/i.test(file.name) || file.type === 'text/csv';
          const sheets = isCsv ? [{ name: 'CSV', rows: [] }] : await XL.read(file);
          if (isCsv) { const text = await readText(file), lines = text.replace(/^\ufeff/, '').split(/\r?\n/).filter((l) => l.trim()); const splitLine = (l) => { const out = []; let cur = '', q = false; for (let i = 0; i < l.length; i++) { const ch = l[i]; if (q) { if (ch === '"' && l[i + 1] === '"') { cur += '"'; i++; } else if (ch === '"') q = false; else cur += ch; } else if (ch === '"') q = true; else if (ch === ',' || ch === ';' || ch === '\t') { out.push(cur); cur = ''; } else cur += ch; } out.push(cur); return out.map((x) => x.trim()); }; sheets[0].rows = lines.map(splitLine); }
          analysis = Pages.analyzeImport(sheets, file.name); filter = analysis.rows.some((r) => r.status === 'error') ? 'all' : 'all'; render(reviewView());
        } catch (ex) { UI.error(ex instanceof AppError ? ex : new AppError('تعذر قراءة الملف. تأكد أنه ملف Excel سليم')); }
      };
      UI.on(form, 'click', '[data-imp]', async (e, el) => {
        const act = el.dataset.imp;
        if (act === 'template') Pages.usersTemplate();
        else if (act === 'pick') { const [f] = await UI.pickFiles({ accept: '.xlsx,.csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/csv', multiple: false }); load(f); }
        else if (act === 'again') { analysis = null; render(pickView()); }
        else if (act === 'run') {
          const v = UI.formValues(form), prog = $('.imp-progress', box), bar = $('.imp-progress i', box), txt = $('.imp-progress span', box);
          prog.hidden = false; $$('[data-imp]', box).forEach((b) => { b.disabled = true; });
          try { result = await Pages.runImport(analysis, { mode: v.pwmode || 'random', update: Number(v.update) === 1 }, (d, t) => { bar.style.width = `${Math.round((d / t) * 100)}%`; txt.textContent = `تمت معالجة ${fmtNum(d)} من ${fmtNum(t)}`; }); render(doneView()); UI.confetti(); }
          catch (ex) { UI.error(ex); $$('[data-imp]', box).forEach((b) => { b.disabled = false; }); prog.hidden = true; }
        } else if (act === 'creds' && result) {
          downloadBlob(XL.write([{ name: 'الحسابات', widths: [32, 16, 16, 18, 12, 28, 26], rows: [['الاسم', 'الرقم العسكري', 'اسم المستخدم', 'كلمة المرور الأولية', 'الدور', 'الإدارة', 'المبنى'], ...result.creds] }]), `حسابات-المستخدمين-${dateInput(now())}.xlsx`);
        }
      });
      UI.on(form, 'change', 'input[name="impfilter"]', (e, el) => { filter = el.value; const mode = (form.querySelector('input[name="pwmode"]:checked') || {}).value, upd = form.querySelector('input[name="update"]'), keepUpd = upd ? upd.checked : true; render(reviewView()); const m = form.querySelector(`input[name="pwmode"][value="${mode}"]`); if (m) m.checked = true; const u2 = form.querySelector('input[name="update"]'); if (u2) u2.checked = keepUpd; });
      const drop = () => $('[data-imp="pick"]', box);
      box.addEventListener('dragover', (e) => { const d = drop(); if (d) { e.preventDefault(); d.classList.add('over'); } });
      box.addEventListener('dragleave', () => { const d = drop(); if (d) d.classList.remove('over'); });
      box.addEventListener('drop', (e) => { const d = drop(); if (!d) return; e.preventDefault(); d.classList.remove('over'); load(e.dataTransfer.files[0]); });
    }
  }).then(() => resolve(!!result));
});

Pages.bulkUsers = (ids, action) => {
  const sup = Auth.user.role === 'supervisor', list = ids.map((id) => Data.c.users.get(id)).filter(Boolean);
  const defs = {
    department: { title: 'تحديد الإدارة', icon: 'building', field: { name: 'v', label: 'الإدارة', type: 'select', options: UI.opts('departments') } },
    location: { title: 'تحديد المبنى', icon: 'pin', field: { name: 'v', label: 'المبنى', type: 'select', options: UI.opts('locations') } },
    role: { title: 'تغيير الدور', icon: 'shield', field: { name: 'v', label: 'الدور الجديد', type: 'select', options: Object.entries(ROLE_INFO).filter(([k]) => sup || !['supervisor', 'support_manager'].includes(k)).map(([k, r]) => ({ value: k, label: r.label })) } },
    active: { title: 'تفعيل أو إيقاف', icon: 'lock', field: { name: 'v', label: 'الحالة', type: 'select', options: [{ value: '1', label: 'تفعيل الحسابات' }, { value: '0', label: 'إيقاف الحسابات' }] } }
  }, d = defs[action];
  if (!d || !list.length) return Promise.resolve(false);
  return UI.modal({
    title: `${d.title} — ${arCount(list.length, AR.user)}`, icon: d.icon, size: 'sm',
    body: html`<p class="muted" style="margin-bottom:12px;line-height:1.8">${list.slice(0, 5).map((u) => u.name).join('، ')}${list.length > 5 ? ` و${fmtNum(list.length - 5)} آخرين` : ''}</p>${UI.field(d.field)}`,
    actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'تطبيق', kind: 'primary', icon: 'check', submit: true, handler: async (form) => {
      const v = form.querySelector('[name="v"]').value; if (v === '') throw new AppError('اختر القيمة أولاً');
      const t = now(), me = Auth.user.id, recs = [];
      for (const u of list) { const r = await DB.get('users', u.id); if (!r) continue; if ((action === 'role' || action === 'active') && r.id === me) continue; if (action === 'role' && !sup && ['supervisor', 'support_manager'].includes(r.role)) continue; if (action === 'department') r.departmentId = v; if (action === 'location') r.locationId = v; if (action === 'role') r.role = v; if (action === 'active') r.active = Number(v); r.updatedAt = t; recs.push(r); }
      await DB.bulkPut('users', recs); await Data.refresh('users'); await Data.log('update', 'user', '', `${d.title} لعدد ${recs.length} من المستخدمين`); Bus.emit('users');
      UI.toast(`تم التطبيق على ${arCount(recs.length, AR.user)}`); return true;
    } }]
  });
};

/* ── الترحيب عند أول دخول: كلمة مرور خاصة واختيار المبنى ── */
Pages.welcome = async (ctx) => {
  const u = Auth.user, needPw = !!u.mustChangePassword, info = ROLE_INFO[u.role] || ROLE_INFO.department, locs = Data.list('locations');
  if (!needPw) return Router.go(u.role === 'monitor' ? '/monitor' : '/dashboard');
  ctx.view.innerHTML = String(html`<div class="login welcome"><section class="login-panel"><form class="login-card" id="wForm" novalidate>
    <div class="crest-wrap"><img class="crest" src="${ASSETS.logo}" alt=""></div>
    <div><h1>أهلاً ${u.name.split(/\s+/)[0]}، لنُكمل حسابك</h1><p class="lead">${info.label}${u.departmentId ? ` — ${Data.nameOf('departments', u.departmentId)}` : ''}</p></div>
    ${needPw ? html`<div class="w-sec"><h3>1. اختر كلمة مرور خاصة بك</h3><div class="field"><label for="wn">كلمة المرور الجديدة</label><div class="input-icon">${UI.icon('lock')}<input id="wn" name="next" type="password" autocomplete="new-password"></div><div class="strength" id="wStr"><i></i><i></i><i></i><i></i></div><small class="hint" style="color:#8FA3BD">8 أحرف على الأقل تتضمن حروفاً وأرقاماً</small></div><div class="field"><label for="wc">تأكيد كلمة المرور</label><div class="input-icon">${UI.icon('lock')}<input id="wc" name="confirm" type="password" autocomplete="new-password"></div></div></div>` : ''}
    <div class="w-sec" hidden><h3>${needPw ? '2. ' : ''}أين تعمل؟</h3>
      <div class="field"><label for="wd">الإدارة التي تعمل بها<em>*</em></label><select id="wd" name="departmentId"><option value="">اختر إدارتك...</option>${Data.list('departments').map((d) => html`<option value="${d.id}"${u.departmentId === d.id ? raw(' selected') : ''}>${d.name}</option>`)}</select><small class="hint">اختر من القائمة الكاملة، ويضيف المشرف أي إدارة جديدة من الإعدادات.</small></div>
      ${u.role === 'supervisor' ? '' : html`<div class="field"><label>المبنى الذي تعمل فيه<em>*</em></label><div class="bld-pick">${locs.map((l) => html`<label><input type="radio" name="locationId" value="${l.id}"${u.locationId === l.id ? raw(' checked') : ''}><span>${UI.icon('building')}${l.name}</span></label>`)}</div></div>`}
      <div class="field"><label for="wo">المكتب</label><input id="wo" name="office" value="${u.office || ''}" placeholder="مثال: مكتب 214 - الطابق الثاني"></div>
      <div class="field"><label for="wp">رقم الهاتف</label><input id="wp" name="phone" type="tel" dir="ltr" value="${u.phone || ''}"></div>
    </div>
    <p class="form-error" id="wErr" role="alert" hidden></p>
    <button class="btn btn-primary btn-lg btn-block" type="submit">${UI.icon('check')} حفظ والدخول إلى النظام</button>
    <button type="button" class="btn btn-ghost btn-block" data-act="out" style="color:#9FB2CA">${UI.icon('logout')} تسجيل الخروج</button>
  </form></section>${Pages.scene('خطوة واحدة وتصبح جاهزاً', 'حدّد مكان عملك ليصل إليك الفني بسرعة عند تقديم أي بلاغ.')}</div>`);
  const f = $('#wForm', ctx.view), err = $('#wErr', ctx.view);
  const nx = $('#wn', ctx.view); if (nx) nx.addEventListener('input', () => { $('#wStr', ctx.view).dataset.s = nx.value ? Data.users.strength(nx.value) : 0; });
  UI.parallax($('#scene', ctx.view));
  $('[data-act="out"]', ctx.view).onclick = () => Shell.logout();
  f.addEventListener('submit', async (e) => {
    e.preventDefault(); err.hidden = true; const v = UI.formValues(f), btn = f.querySelector('[type=submit]');
    try {
      if (needPw) { if (v.next !== v.confirm) throw new AppError('كلمتا المرور غير متطابقتين'); if (u.militaryNo && v.next === u.militaryNo) throw new AppError('لا تستخدم رقمك العسكري كلمة مرور'); Data.users.checkPolicy(v.next); }
      UI.busy(btn, true); await new Promise((r) => setTimeout(r, 40));
      if (needPw) await Data.users.setPassword(u.id, v.next, false);
      const rec = await DB.get('users', u.id);
      Object.assign(rec, { locationId: v.locationId || rec.locationId || '', departmentId: v.departmentId || rec.departmentId || '', office: String(v.office || '').trim(), phone: String(v.phone || '').trim(), mustChangePassword: 0, updatedAt: now() });
      await DB.put('users', rec); await Data.refresh('users'); Auth.user = rec;
      await Data.log('update', 'user', rec.id, 'إكمال بيانات الحساب عند أول دخول');
      UI.confetti(); Router.go('/dashboard');
    } catch (ex) { err.textContent = ex instanceof AppError ? ex.message : 'تعذر الحفظ، حاول مرة أخرى'; err.hidden = false; UI.busy(btn, false); }
  });
  const first = $('#wn', ctx.view) || $('#wo', ctx.view); if (first) first.focus();
};

