const lookupModalBase = Pages.lookupModal;
Pages.lookupModal = async (store, id) => {
  if (store !== 'categories') return lookupModalBase(store, id);
  const rec = id ? Data.c.categories.get(id) : { illustration: 'box' }, staff = Data.list('users').filter((u) => u.active && canUser(u, 'tickets.work'));
  const owners = new Set(staff.filter((u) => (u.categories || []).includes(id)).map((u) => u.id));
  return UI.modal({
    title: `${id ? 'تعديل فئة' : 'فئة بلاغات جديدة'}`, icon: 'tag', size: 'lg',
    body: html`${UI.fields([{ name: 'name', label: 'اسم الفئة', required: true }, { name: 'order', label: 'الترتيب', type: 'number', min: 0 }], rec)}
      <div class="field mt"><label>المسؤولون عن هذه الفئة</label><div class="chip-pick">${staff.length ? staff.map((u) => html`<label><input type="checkbox" data-own="${u.id}"${owners.has(u.id) ? raw(' checked') : ''}><span>${u.name} — ${ROLES[u.role]}</span></label>`) : html`<span class="faint small">لا يوجد فنيون أو إداريون بعد</span>`}</div><small class="hint">تُسند بلاغات هذه الفئة تلقائياً لمن تختاره هنا.</small></div>
      <div class="field mt"><label for="cfile">استمارة الفئة (اختياري)</label>${rec.formFile ? html`<div class="form-bar" style="margin-bottom:8px">${UI.icon('file')}<div class="grow"><b>${rec.formFile.name}</b><div class="t-sub">${fmtBytes(rec.formFile.size)}</div></div><button type="button" class="btn btn-sm btn-soft" data-catform="${id}">${UI.icon('download')} تحميل</button></div>` : ''}<input id="cfile" name="formFile" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,image/*">${UI.field({ name: 'formRequired', type: 'switch', text: 'إرفاق المستند بعد تعبئته إلزامي عند تقديم البلاغ' }, rec.formRequired ? 1 : 0)}<small class="hint">تظهر للموظفين عند تقديم بلاغ في هذه الفئة وفي صفحة البلاغ. الحد 3 ميجابايت.</small></div>
      <div class="field mt"><label>صورة الفئة <small class="faint">(من مخزن الصور${ImgLib.canManage() ? '، أو ارفع صورة جديدة' : ''})</small></label>${UI.imgPicker('image', id ? CatIcon.ref(id) : 'i3d:box')}</div>`,
    onMount: (form) => UI.bindImgPicker(form),
    actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'حفظ', kind: 'primary', icon: 'check', submit: true, handler: async (form) => {
      const v = UI.formValues(form); if (!String(v.name).trim()) throw new AppError('اسم الفئة مطلوب');
      const fi = form.querySelector('[name="formFile"]'), file = fi && fi.files && fi.files[0];
      let formFile = rec.formFile || null;
      if (file) { if (file.size > 3 * 1024 * 1024) throw new AppError('حجم الملف أكبر من 3 ميجابايت'); formFile = { name: file.name, type: file.type, size: file.size, at: now(), data: await fileToData(file) }; }
      const saved = await Data.saveRecord('categories', { ...rec, ...v, image: ImgLib.valid(v.image) ? v.image : rec.image || '', name: v.name.trim(), order: Number(v.order) || 0, formFile, formRequired: formFile && Number(v.formRequired) ? 1 : 0 }, 'فئة');
      const picked = new Set($$('[data-own]:checked', form).map((x) => x.dataset.own)), changed = [];
      for (const u of staff) { const has = (u.categories || []).includes(saved.id), want = picked.has(u.id); if (has === want) continue; const rec2 = await DB.get('users', u.id); rec2.categories = want ? [...new Set([...(rec2.categories || []), saved.id])] : (rec2.categories || []).filter((c) => c !== saved.id); rec2.updatedAt = now(); changed.push(rec2); }
      if (changed.length) { await DB.bulkPut('users', changed); await Data.refresh('users'); await Data.log('update', 'user', '', `تحديث مسؤولي فئة ${saved.name}`); Bus.emit('users'); }
      UI.toast('تم الحفظ'); return saved;
    } }]
  });
};

/* ── تصعيد البلاغات المتأخرة ── */
const Escalate = {
  async run() {
    try {
      if (!Auth.user || !canUser(Auth.user, 'tickets.work')) return;
      if (!(await Jobs.claim('escalate:at', 4 * MIN))) return;
      const after = Number(Data.c.settings.escalateAfter || 60), late = [];
      await DB.each('tickets', { index: 'openDue', range: KR(1, now() - after * MIN) }, (t) => { if (!t.escalated) late.push(t); });
      if (!late.length) return;
      for (const t of late.slice(0, 40)) { const rec = await DB.get('tickets', t.id); if (!rec || rec.escalated) continue; rec.escalated = now(); await DB.put('tickets', rec); }
      const managers = Data.list('users').filter((u) => u.active && canUser(u, 'tickets.manage')).map((u) => u.id);
      if (managers.length) await Data.notify(managers, { title: `تنبيه تأخر: ${arCount(late.length, AR.ticket)} تجاوزت موعدها`, body: late.slice(0, 3).map((t) => `${t.number} ${t.title}`).join('، '), link: '/tickets?scope=overdue', kind: 'ticket' });
    } catch (e) { console.warn('escalate', e); }
  }
};
setTimeout(() => Escalate.run(), 25000);
setInterval(() => Escalate.run(), 5 * MIN);

/* ── عهدة الإدارات: ربط المخزن بالإدارات، والتقارير، والإغلاق التلقائي ── */
MOVES.dept_return = { label: 'إرجاع من إدارة', sign: 1 };
MOVES.dept_transfer = { label: 'نقل بين الإدارات', sign: 0 };
MOVE_TONE.dept_return = 'green'; MOVE_TONE.dept_transfer = 'violet';
MOVES.dept_opening = { label: 'إضافة عهدة مباشرة', sign: 0 }; MOVE_TONE.dept_opening = 'brass';
AR.day = ['يوم واحد', 'يومين', 'أيام', 'يوماً', 'يوم'];

Data.dept = {
  async of(departmentId) { return (await DB.getAll('deptStock', 'departmentId', KR(departmentId))).filter((r) => r.qty > 0); },
  async ofItem(itemId) { return (await DB.getAll('deptStock', 'itemId', KR(itemId))).filter((r) => r.qty > 0); },
  async all() {
    const m = new Map();
    await DB.each('deptStock', {}, (r) => { if (r.qty > 0) { const x = m.get(r.departmentId) || { departmentId: r.departmentId, units: 0, skus: 0 }; x.units += r.qty; x.skus += 1; m.set(r.departmentId, x); } });
    return [...m.values()].sort((a, b) => b.units - a.units);
  },
  async returnToStore({ departmentId, itemId, warehouseId, qty, note = '', party = '' }) {
    const n = Math.floor(Number(qty)); if (!(n > 0)) throw new AppError('أدخل كمية صحيحة أكبر من صفر');
    if (!Data.c.warehouses.get(warehouseId)) throw new AppError('اختر المخزن المستلم');
    const at = now(), me = Auth.user.id; let result;
    await DB.run(['items', 'stock', 'movements', 'deptStock'], async (T) => {
      const item = await T.get('items', itemId); if (!item) throw new AppError('الصنف غير موجود');
      const ds = await T.get('deptStock', [departmentId, itemId]);
      if (!ds || ds.qty < n) throw new AppError(`الموجود في عهدة ${Data.nameOf('departments', departmentId)} هو ${ds ? ds.qty : 0} فقط`);
      const st = (await T.get('stock', [warehouseId, itemId])) || { warehouseId, itemId, qty: 0 };
      ds.qty -= n; st.qty += n; item.onHand += n; ds.updatedAt = at; st.updatedAt = at; item.updatedAt = at;
      result = { id: uid('mv'), type: 'dept_return', itemId, warehouseId, qty: n, delta: n, balance: st.qty, at, userId: me, note, ref: '', party, departmentId };
      await T.put('deptStock', ds); await T.put('stock', st); await T.put('items', item); await T.put('movements', result);
    });
    await Data.log('move', 'inventory', itemId, `إرجاع ${fmtNum(n)} من عهدة ${Data.nameOf('departments', departmentId)} إلى ${Data.nameOf('warehouses', warehouseId)}`);
    Bus.emit('inventory', { itemId }); return result;
  },
  async transfer({ departmentId, toDepartmentId, itemId, qty, note = '' }) {
    const n = Math.floor(Number(qty)); if (!(n > 0)) throw new AppError('أدخل كمية صحيحة أكبر من صفر');
    if (!toDepartmentId || toDepartmentId === departmentId) throw new AppError('اختر إدارة مختلفة للنقل إليها');
    const at = now(), me = Auth.user.id; let result;
    await DB.run(['movements', 'deptStock'], async (T) => {
      const from = await T.get('deptStock', [departmentId, itemId]);
      if (!from || from.qty < n) throw new AppError(`الموجود في عهدة ${Data.nameOf('departments', departmentId)} هو ${from ? from.qty : 0} فقط`);
      const to = (await T.get('deptStock', [toDepartmentId, itemId])) || { departmentId: toDepartmentId, itemId, qty: 0 };
      from.qty -= n; to.qty += n; from.updatedAt = at; to.updatedAt = at;
      result = { id: uid('mv'), type: 'dept_transfer', itemId, warehouseId: '', qty: n, delta: 0, balance: null, at, userId: me, note, ref: '', party: Data.nameOf('departments', toDepartmentId), departmentId, toDepartmentId };
      await T.put('deptStock', from); await T.put('deptStock', to); await T.put('movements', result);
    });
    await Data.log('move', 'inventory', itemId, `نقل ${fmtNum(n)} من ${Data.nameOf('departments', departmentId)} إلى ${Data.nameOf('departments', toDepartmentId)}`);
    Bus.emit('inventory', { itemId }); return result;
  },
  async report({ departments = [], warehouseId = '', categoryId = '', q = '' } = {}) {
    const qn = normalizeAr(q), items = new Map();
    await DB.each('items', {}, (i) => { if ((!categoryId || i.categoryId === categoryId) && (!qn || String(i.search).includes(qn))) items.set(i.id, { item: i, store: 0, byWh: {}, depts: {}, deptTotal: 0 }); });
    await DB.each('stock', {}, (s) => { const r = items.get(s.itemId); if (!r || s.qty <= 0) return; if (warehouseId && s.warehouseId !== warehouseId) return; r.store += s.qty; r.byWh[s.warehouseId] = (r.byWh[s.warehouseId] || 0) + s.qty; });
    const pick = new Set(departments);
    await DB.each('deptStock', {}, (d) => { const r = items.get(d.itemId); if (!r || d.qty <= 0) return; if (pick.size && !pick.has(d.departmentId)) return; r.depts[d.departmentId] = (r.depts[d.departmentId] || 0) + d.qty; r.deptTotal += d.qty; });
    const rows = [...items.values()].filter((r) => r.store > 0 || r.deptTotal > 0).map((r) => ({ ...r, total: r.store + r.deptTotal })).sort((a, b) => b.total - a.total);
    return { rows, store: rows.reduce((s, r) => s + r.store, 0), dept: rows.reduce((s, r) => s + r.deptTotal, 0), skus: rows.length };
  }
};

Data.dept.rebuild = async () => {
  const map = new Map(), key = (d, i) => `${d}|${i}`;
  await DB.each('movements', { index: 'at' }, (m) => {
    if (!m.itemId) return;
    const add = (dep, q) => { if (!dep) return; const k = key(dep, m.itemId); map.set(k, (map.get(k) || 0) + q); };
    if (m.type === 'issue') add(m.departmentId, m.qty);
    else if (m.type === 'dept_return') add(m.departmentId, -m.qty);
    else if (m.type === 'dept_opening') add(m.departmentId, m.qty);
    else if (m.type === 'dept_transfer') { add(m.departmentId, -m.qty); add(m.toDepartmentId, m.qty); }
  });
  const old = await DB.getAll('deptStock');
  for (const r of old) await DB.del('deptStock', [r.departmentId, r.itemId]);
  const rows = [...map.entries()].filter(([, q]) => q > 0).map(([k, qty]) => { const [departmentId, itemId] = k.split('|'); return { departmentId, itemId, qty, updatedAt: now() }; });
  await DB.bulkPut('deptStock', rows);
  await Data.refresh(); await Data.log('update', 'inventory', '', `إعادة بناء عهد الإدارات من سجل الحركات: ${fmtNum(rows.length)} سجل`);
  Bus.emit('inventory', {});
  return { rows: rows.length, units: rows.reduce((s, r) => s + r.qty, 0) };
};

