/* مسار البلاغ خطوة بخطوة */
const FLOW_STEPS = [
  { k: 'new', label: 'وصل البلاغ', icon: 'inbox', hint: 'بانتظار استلام أحد الفنيين' },
  { k: 'assigned', label: 'استلام الفني', icon: 'user-plus', hint: 'اضغط «بدء العمل» عند مباشرة المعالجة' },
  { k: 'in_progress', label: 'قيد المعالجة', icon: 'play', hint: 'سجّل ما تم وأضف القطع المستخدمة إن وُجدت' },
  { k: 'resolved', label: 'تم الحل', icon: 'check', hint: 'بانتظار تأكيد المستفيد أو الإغلاق' },
  { k: 'closed', label: 'مغلق', icon: 'lock', hint: 'اكتمل البلاغ' }
];
Pages.ticketFlow = (t) => {
  const order = ['new', 'assigned', 'in_progress', 'resolved', 'closed'];
  const cur = t.status === 'waiting' ? 'in_progress' : t.status;
  const idx = Math.max(0, order.indexOf(cur));
  return UI.panel({ title: 'مسار العمل', icon: 'pulse', body: html`<ol class="flow">${FLOW_STEPS.map((s, i) => html`<li class="flow-step${i < idx ? ' done' : i === idx ? ' now' : ''}"><span class="fs-dot">${i < idx ? UI.icon('check') : UI.icon(s.icon)}</span><div><b>${s.label}</b>${i === idx ? html`<div class="t-sub">${t.status === 'waiting' ? 'معلّق مؤقتاً: بانتظار قطعة أو رد المستفيد' : s.hint}</div>` : ''}</div></li>`)}</ol>` });
};

/* مرفقات الاستفسارات وحذفها تلقائياً وتقاريرها */
Data.chat.attach = async (chatId, file) => {
  if (file.size > 3 * 1024 * 1024) throw new AppError('حجم الملف أكبر من 3 ميجابايت');
  const data = await fileToData(file);
  const chat = await DB.get('chats', chatId); if (!chat) throw new AppError('المحادثة غير موجودة');
  const staff = isChatStaff(), msg = { id: uid('cm'), chatId, userId: Auth.user.id, text: `📎 ${file.name}`, at: now(), staff: staff ? 1 : 0, file: { name: file.name, type: file.type, size: file.size, data } };
  await DB.put('chatMsgs', msg);
  chat.lastAt = msg.at; chat.updatedAt = msg.at; chat.lastBy = Auth.user.id; chat.staffClosedAt = 0; chat.userClosedAt = 0;
  if (staff) chat.unreadUser = (chat.unreadUser || 0) + 1; else chat.unreadStaff = (chat.unreadStaff || 0) + 1;
  await DB.put('chats', chat); Bus.emit('chat', {});
  return msg;
};
const ChatPurge = {
  async run() {
    try {
      if (!Auth.user) return;
      if (!(await Jobs.claim('chatpurge:at', 6 * 60 * MIN))) return;
      const chats = await DB.getAll('chats'), keep = [];
      for (const c of chats) {
        const closedAt = c.status === 'closed' ? Math.max(c.userClosedAt || 0, c.staffClosedAt || 0, c.updatedAt || 0) : 0;
        if (!closedAt || now() - closedAt < 3 * DAY) continue;
        const msgs = await DB.getAll('chatMsgs', 'chatId', KR(c.id));
        const stat = { id: uid('cs'), key: `chatstat:${c.id}`, value: { subject: c.subject, userId: c.userId, departmentId: c.departmentId, staffId: c.staffId, at: c.createdAt, closedAt, msgs: msgs.length } };
        await DB.put('meta', { key: stat.key, value: stat.value });
        for (const m of msgs) await DB.del('chatMsgs', m.id);
        await DB.del('chats', c.id);
        keep.push(c.id);
      }
      if (keep.length) Bus.emit('chat', {});
    } catch (e) { console.warn('chat purge', e); }
  }
};
setTimeout(() => ChatPurge.run(), 60000);
setInterval(() => ChatPurge.run(), 60 * MIN);
Pages.chatReport = async (ctx) => {
  const rows = await DB.getAll('chats'), archived = (await DB.getAll('meta')).filter((m) => String(m.key).startsWith('chatstat:')).map((m) => m.value);
  const all = [...rows.map((c) => ({ userId: c.userId, departmentId: c.departmentId, at: c.createdAt, closedAt: c.status === 'closed' ? c.updatedAt : 0 })), ...archived];
  if (!ctx.alive()) return;
  const byDep = new Map(), byUser = new Map();
  all.forEach((c) => { byDep.set(c.departmentId, (byDep.get(c.departmentId) || 0) + 1); byUser.set(c.userId, (byUser.get(c.userId) || 0) + 1); });
  const month = all.filter((c) => now() - c.at < 30 * DAY).length;
  ctx.view.innerHTML = String(html`${UI.pageHead({ title: 'تقرير الاستفسارات', sub: 'أعداد الاستفسارات والجهات الطالبة دون الاطلاع على محتوى المحادثات', illu: 'chart' })}
    <div class="kpis">${UI.kpi({ label: 'إجمالي الاستفسارات', icon: 'bell', tone: 'violet', value: all.length })}${UI.kpi({ label: 'خلال 30 يوماً', icon: 'clock', tone: 'sky', value: month })}${UI.kpi({ label: 'مفتوحة حالياً', icon: 'pulse', tone: 'amber', value: rows.filter((c) => c.status !== 'closed').length })}${UI.kpi({ label: 'إدارات مشاركة', icon: 'building', tone: 'teal', value: byDep.size })}</div>
    <div class="grid g-2 mt">
      ${UI.panel({ title: 'حسب الإدارة', icon: 'building', body: byDep.size ? UI.chart.hbars([...byDep.entries()].sort((a, b) => b[1] - a[1]).slice(0, 10).map(([d, n], i) => ({ label: Data.nameOf('departments', d, 'غير محدد'), value: n, tone: TONES[i % TONES.length] }))) : UI.noData() })}
      ${UI.panel({ title: 'أكثر المستفيدين', icon: 'users', body: byUser.size ? html`<div class="list">${[...byUser.entries()].sort((a, b) => b[1] - a[1]).slice(0, 10).map(([u, n]) => html`<div class="list-row">${UI.avatar(u, 'av-sm')}<div class="grow ellipsis"><b>${Data.userName(u)}</b><div class="t-sub">${Data.nameOf('departments', (Data.c.users.get(u) || {}).departmentId, '')}</div></div>${UI.chip('sky', fmtNum(n))}</div>`)}</div>` : UI.noData() })}
    </div>
    <p class="hint mt">تُحذف محادثات الاستفسارات بعد ثلاثة أيام من إغلاقها لتوفير المساحة، وتبقى هذه الإحصاءات فقط.</p>`);
  UI.hydrate(ctx.view);
};

/* سياسة الصورة الشخصية */
const avatarPolicy = () => Data.c.settings.avatars || 'off';
Pages.avatarModal = async () => {
  const policy = avatarPolicy(), me = Auth.user || {};
  const ICONS = ['computer', 'laptop', 'printer', 'scanner', 'network', 'server', 'tools', 'card', 'key', 'bell', 'book', 'clipboard', 'shelf', 'display', 'phone', 'tablet', 'wifi', 'toner', 'camera', 'projector', 'headset', 'fingerprint', 'router', 'netswitch', 'barcode', 'smartcard', 'mic', 'webcam'];
  return UI.modal({
    title: 'الصورة أو الأيقونة الشخصية', icon: 'user', size: 'lg',
    body: html`<div class="u-sec"><h3>${UI.icon('box')} اختر أيقونة</h3><p class="muted small" style="margin:0 0 8px">أيقونات جاهزة لكل الحسابات، لا تستهلك مساحة وتظهر فوراً.</p>
        <div class="tiles sm cat-pick avatar-pick">${ICONS.map((k) => html`<label><input type="radio" name="avatarIcon" value="${k}"${me.avatarIcon === k ? raw(' checked') : ''}><span class="tile">${UI.illu(k)}<b>${ILLU_LABELS[k] || k}</b></span></label>`)}<label><input type="radio" name="avatarIcon" value=""${!me.avatarIcon ? raw(' checked') : ''}><span class="tile">${UI.icon('user')}<b>الحروف الأولى</b></span></label></div></div>
      ${policy === 'off' ? html`<p class="hint mt">${UI.icon('info')} رفع الصور الشخصية معطّل من الإعدادات، ويمكن استخدام الأيقونات.</p>` : html`<div class="u-sec mt"><h3>${UI.icon('user')} أو ارفع صورة</h3><p class="muted small" style="margin:0 0 8px">${policy === 'approval' ? 'تُرسل الصورة لاعتماد المشرف قبل ظهورها.' : 'ستظهر صورتك مباشرة بعد الحفظ.'}</p>
        <div class="field"><label for="avf">اختر صورة</label><input id="avf" name="photo" type="file" accept="image/*"><small class="hint">تُصغَّر الصورة تلقائياً ولا تتجاوز 200 كيلوبايت.</small></div></div>`}`,
    actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'حفظ', kind: 'primary', icon: 'check', submit: true, handler: async (form) => {
      const iconSel = form.querySelector('[name="avatarIcon"]:checked');
      const fEl = form.querySelector('[name="photo"]');
      const f = fEl ? (fEl.files || [])[0] : null;
      if (!f) {
        const rec0 = await DB.get('users', Auth.user.id);
        rec0.avatarIcon = iconSel ? iconSel.value : '';
        if (!rec0.avatarIcon) delete rec0.avatarIcon;
        rec0.updatedAt = now(); await DB.put('users', rec0); await Data.refresh('users'); Auth.user = await DB.get('users', Auth.user.id);
        UI.toast('حُدِّثت أيقونتك'); return true;
      }
      const data = await shrinkImage(f, 200);
      const rec = await DB.get('users', Auth.user.id);
      if (policy === 'approval') { rec.avatarPending = data; await Data.notify(Data.list('users').filter((u) => u.active && u.role === 'supervisor').map((u) => u.id), { title: `طلب اعتماد صورة شخصية: ${rec.name}`, body: 'راجع الطلب من صفحة المستخدمين', link: '/users', kind: 'user' }); }
      else rec.avatar = data;
      rec.updatedAt = now(); await DB.put('users', rec); await Data.refresh('users'); Auth.user = await DB.get('users', Auth.user.id);
      UI.toast(policy === 'approval' ? 'أُرسلت الصورة لاعتماد المشرف' : 'حُفظت صورتك'); return true;
    } }]
  });
};
const shrinkImage = (file, maxPx = 200) => new Promise((res, rej) => {
  const r = new FileReader();
  r.onload = () => { const img = new Image(); img.onload = () => { const s = Math.min(maxPx / img.width, maxPx / img.height, 1), cv = document.createElement('canvas'); cv.width = Math.round(img.width * s); cv.height = Math.round(img.height * s); cv.getContext('2d').drawImage(img, 0, 0, cv.width, cv.height); res(cv.toDataURL('image/jpeg', 0.82)); }; img.onerror = () => rej(new AppError('تعذر قراءة الصورة')); img.src = String(r.result); };
  r.onerror = () => rej(new AppError('تعذر قراءة الملف'));
  r.readAsDataURL(file);
});
Data.users.avatarDecision = async (id, approve) => {
  if (!canUser(Auth.user, 'users.manage')) throw new AppError('للمشرف فقط');
  const rec = await DB.get('users', id); if (!rec) return;
  if (approve) { rec.avatar = rec.avatarPending || rec.avatar; }
  delete rec.avatarPending; rec.updatedAt = now();
  await DB.put('users', rec); await Data.refresh('users');
  await Data.notify([id], { title: approve ? 'اعتُمدت صورتك الشخصية' : 'لم تُعتمد صورتك الشخصية', body: '', link: '/profile', kind: 'user' });
  Bus.emit('users', {});
};
Data.users.removeAvatar = async (id) => {
  if (!canUser(Auth.user, 'users.manage')) throw new AppError('للمشرف فقط');
  const rec = await DB.get('users', id); if (!rec) return;
  delete rec.avatar; delete rec.avatarPending; rec.updatedAt = now();
  await DB.put('users', rec); await Data.refresh('users'); Bus.emit('users', {});
  UI.toast('أُزيلت الصورة');
};

