/* حقول برنامج مسار: عدة أشخاص بأسمائهم وأرقامهم */
Forms.codeBlock = (list = []) => html`<div class="persons-box" data-codes>
  <div class="row" style="justify-content:space-between;align-items:center;margin-bottom:8px"><b class="small">${UI.icon('users')} الأشخاص المطلوب إصدار رمز لهم</b><span class="row" style="gap:6px"><input class="qty-in" type="number" min="1" max="30" value="${Math.max(1, list.length || 1)}" data-codecount aria-label="عدد الأشخاص"><button type="button" class="btn btn-ghost btn-sm" data-act="setcodes">${UI.icon('refresh')} تجهيز الخانات</button></span></div>
  <div class="persons-list">${(list.length ? list : [{}]).map((p, i) => Forms.codeRow(p, i))}</div>
  <small class="hint">اكتب عدد الأشخاص ثم اضغط «تجهيز الخانات» لتظهر خانة اسم ورقم عسكري لكل شخص.</small></div>`;
Forms.codeRow = (p = {}, i = 0) => html`<div class="person-row" data-code="${i}">
  <input name="cn_${i}" value="${p.name || ''}" placeholder="الاسم الكامل">
  <input name="cm_${i}" value="${p.militaryNo || ''}" placeholder="الرقم العسكري" dir="ltr">
  <button type="button" class="icon-btn" data-delcode="${i}" aria-label="حذف">${UI.icon('trash')}</button></div>`;
Forms.readCodes = (root) => {
  const out = [];
  $$('[data-code]', root).forEach((row) => {
    const i = row.dataset.code, name = String((root.querySelector(`[name="cn_${i}"]`) || {}).value || '').trim();
    const no = String((root.querySelector(`[name="cm_${i}"]`) || {}).value || '').trim();
    if (name || no) out.push({ name, militaryNo: no });
  });
  return out;
};
document.addEventListener('click', (e) => {
  const set = e.target.closest('[data-act="setcodes"]');
  if (set) {
    const box = set.closest('[data-codes]'); if (!box) return;
    const n = clamp(Number((box.querySelector('[data-codecount]') || {}).value) || 1, 1, 30);
    const cur = Forms.readCodes(box), list = box.querySelector('.persons-list');
    list.innerHTML = String(Array.from({ length: n }, (_, i) => Forms.codeRow(cur[i] || {}, i)));
    UI.hydrate(list);
    return;
  }
  const del = e.target.closest('[data-delcode]');
  if (del) { const row = del.closest('.person-row'); if (row) row.remove(); }
});

/* عنوان الطلب حسب الفئة */
const CAT_TITLE_LABEL = { card: 'موضوع الطلب', path_code: 'موضوع الطلب', backup: 'موضوع الطلب', service_request: 'موضوع الطلب', email: 'موضوع الطلب', ink: 'موضوع الطلب' };
Forms.titleLabel = (catId) => CAT_TITLE_LABEL[catId] || 'عنوان مختصر للمشكلة';

/* ── قراءة الباركود و QR: بالكاميرا أو بقارئ الشفرات، مع البحث والصرف السريع ── */
const SCAN_FORMATS = ['qr_code', 'code_128', 'code_39', 'ean_13', 'ean_8', 'upc_a', 'upc_e', 'itf', 'data_matrix', 'pdf417', 'codabar'];
const scanSupported = () => typeof window !== 'undefined' && 'BarcodeDetector' in window;
Data.assets.bySerialOrTag = async (code) => {
  const c = String(code || '').trim(); if (!c) return null;
  const direct = await Data.assets.bySerial(c);
  if (direct) return direct;
  const all = await DB.getAll('assets');
  const norm = (x) => String(x || '').trim().toUpperCase();
  return all.find((a) => norm(a.tag) === norm(c)) || all.find((a) => norm(a.serial) === norm(c)) || null;
};
Pages.scanModal = ({ title = 'مسح الرمز', hint = 'وجّه الكاميرا إلى الباركود أو رمز QR، أو استخدم قارئ الشفرات.' } = {}) => {
  let stream = null, stop = false, detector = null;
  return UI.modal({
    title, icon: 'search', size: 'lg',
    body: html`<div class="scan-wrap">
        <div class="scan-view" data-scanview>${scanSupported() ? html`<video id="scanVideo" playsinline muted></video><div class="scan-frame"></div>` : html`<div class="scan-off">${UI.icon('alert')}<b>الكاميرا غير مدعومة في هذا المتصفح</b><span>استخدم قارئ الشفرات أو اكتب الرقم يدوياً</span></div>`}</div>
        <p class="hint">${hint}</p>
      </div>
      <div class="field mt"><label for="scanIn">قارئ الشفرات أو إدخال يدوي</label><div class="combo"><input id="scanIn" name="code" dir="ltr" placeholder="امسح بالقارئ أو اكتب الرقم ثم اضغط Enter" autocomplete="off"><button type="button" class="combo-btn" data-scan="cam" title="تشغيل الكاميرا">${UI.icon('eye')}</button></div><small class="hint">قارئ الشفرات USB يعمل مباشرة: ضع المؤشر في الخانة وامسح.</small></div>
      <div class="scan-status" data-scanstatus hidden></div>`,
    onMount: async (form, finish) => {
      const input = $('#scanIn', form), status = form.querySelector('[data-scanstatus]');
      const say = (msg, tone = 'sky') => { status.hidden = false; status.className = `scan-status tone-${tone}`; status.textContent = msg; };
      const done = (code) => { stop = true; if (stream) stream.getTracks().forEach((t) => t.stop()); finish(String(code || '').trim()); };
      input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); if (input.value.trim()) done(input.value); } });
      setTimeout(() => input.focus(), 120);
      const startCam = async () => {
        if (!scanSupported()) { say('المتصفح لا يدعم قراءة الرموز بالكاميرا، استخدم القارئ أو الإدخال اليدوي', 'amber'); return; }
        try {
          detector = new window.BarcodeDetector({ formats: SCAN_FORMATS.filter((f) => true) });
          stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: { ideal: 'environment' } } });
          const v = $('#scanVideo', form); if (!v) return;
          v.srcObject = stream; await v.play();
          say('جارٍ البحث عن رمز...', 'sky');
          const tick = async () => {
            if (stop || !v.videoWidth) { if (!stop) requestAnimationFrame(tick); return; }
            try { const codes = await detector.detect(v); if (codes && codes.length) { UI.sound('success'); done(codes[0].rawValue); return; } } catch (_) { /* تجاهل */ }
            if (!stop) setTimeout(tick, 220);
          };
          tick();
        } catch (e) { say('تعذر فتح الكاميرا (قد تحتاج اتصالاً آمناً https أو إذناً بالكاميرا)، استخدم القارئ أو الإدخال اليدوي', 'amber'); }
      };
      UI.on(form, 'click', '[data-scan="cam"]', startCam);
      startCam();
      form.addEventListener('modal:close', () => { stop = true; if (stream) stream.getTracks().forEach((t) => t.stop()); });
    },
    actions: [{ label: 'إلغاء', kind: 'ghost', value: null }, { label: 'استخدام المُدخل', kind: 'primary', icon: 'check', submit: true, handler: (form) => { const v = String(($('#scanIn', form) || {}).value || '').trim(); if (!v) throw new AppError('امسح رمزاً أو اكتب الرقم'); return v; } }]
  });
};
UI.scanBtn = (target, cls = 'btn btn-soft') => html`<button type="button" class="${cls}" data-scanfor="${target}">${UI.icon('search')} مسح رمز</button>`;

/* مسح سريع: يفتح الجهاز أو يحدد الوحدة أو يعبّئ خانة */
Pages.scanLookup = async () => {
  const code = await Pages.scanModal({ title: 'بحث بالشفرة', hint: 'امسح ملصق الجهاز لعرض بياناته وموقعه الحالي.' });
  if (!code) return null;
  const asset = await Data.assets.bySerialOrTag(code);
  if (asset) {
    UI.toast(`${asset.serial}${asset.tag ? ` — أصل ${asset.tag}` : ''}: ${ASSET_STATUS[asset.status].label}`);
    await Pages.deviceModal(asset.itemId, asset.status === 'issued' ? { departmentId: asset.departmentId } : {});
    return asset;
  }
  const items = (await DB.getAll('items')).filter((i) => normalizeAr(`${i.sku} ${i.name} ${i.model || ''}`).includes(normalizeAr(code)));
  if (items.length === 1) { await Pages.deviceModal(items[0].id, {}); return items[0]; }
  UI.toast(`لم يُعثر على وحدة أو صنف بالرمز ${code}`, 'warn');
  Router.go(`/inventory/search?q=${encodeURIComponent(code)}`);
  return null;
};
document.addEventListener('click', async (e) => {
  const q = e.target.closest('[data-scanfor]');
  if (!q) return;
  e.preventDefault();
  const target = q.dataset.scanfor;
  if (target === 'lookup') { await Pages.scanLookup(); return; }
  if (target === 'pick') {
    const box = q.closest('.modal-card, form, .field') || document;
    const code = await Pages.scanModal({ title: 'مسح الوحدة', hint: 'امسح ملصق الجهاز لتحديده في القائمة.' });
    if (!code) return;
    const asset = await Data.assets.bySerialOrTag(code);
    const id = asset && asset.id;
    const cb = id ? box.querySelector(`[data-pick="${id}"]`) : null;
    if (cb) { cb.checked = true; cb.dispatchEvent(new Event('change', { bubbles: true })); UI.toast(`تم تحديد ${asset.serial}`); UI.sound('success'); }
    else UI.toast(asset ? `الوحدة ${asset.serial} غير متاحة في هذه القائمة (${ASSET_STATUS[asset.status].label})` : `لا توجد وحدة بالرمز ${code}`, 'warn');
    return;
  }
  const el = document.getElementById(target);
  if (el) { const code = await Pages.scanModal(); if (code) { el.value = code; el.dispatchEvent(new Event('input', { bubbles: true })); el.dispatchEvent(new Event('change', { bubbles: true })); } }
});

/* تصدير التقارير إلى Excel */
Pages.reportExcel = async (win, meta) => {
  const rows = (win && win.created) || [];
  const byCat = new Map(), byTech = new Map(), byDep = new Map();
  rows.forEach((t) => {
    byCat.set(t.categoryId, (byCat.get(t.categoryId) || 0) + 1);
    if (t.assigneeId) byTech.set(t.assigneeId, (byTech.get(t.assigneeId) || 0) + 1);
    byDep.set(t.departmentId, (byDep.get(t.departmentId) || 0) + 1);
  });
  const sheet = (name, head, data, widths) => ({ name, widths, rows: [head, ...data] });
  const book = [
    sheet('البلاغات', ['رقم البلاغ', 'العنوان', 'الفئة', 'الأولوية', 'الحالة', 'الإدارة', 'المسؤول', 'تاريخ الفتح', 'تاريخ الإغلاق'],
      rows.map((t) => [t.number, t.title, Data.nameOf('categories', t.categoryId, ''), (PRIORITY[t.priority] || {}).label || '', (STATUS[t.status] || {}).label || '', Data.nameOf('departments', t.departmentId, ''), t.assigneeId ? Data.userName(t.assigneeId) : '', fmtDateTime(t.createdAt), t.closedAt ? fmtDateTime(t.closedAt) : '']),
      [16, 40, 18, 12, 14, 20, 20, 20, 20]),
    sheet('حسب الفئة', ['الفئة', 'عدد البلاغات'], [...byCat].sort((a, b) => b[1] - a[1]).map(([k, v]) => [Data.nameOf('categories', k, 'غير محدد'), String(v)]), [26, 14]),
    sheet('حسب الإدارة', ['الإدارة', 'عدد البلاغات'], [...byDep].sort((a, b) => b[1] - a[1]).map(([k, v]) => [Data.nameOf('departments', k, 'غير محدد'), String(v)]), [26, 14]),
    sheet('حسب الفني', ['الفني', 'عدد البلاغات'], [...byTech].sort((a, b) => b[1] - a[1]).map(([k, v]) => [Data.userName(k), String(v)]), [26, 14])
  ];
  downloadBlob(XL.write(book), `تقرير-${dateInput(meta.from)}_${dateInput(meta.to)}.xlsx`);
  UI.toast('تم تصدير التقرير إلى Excel');
};

/* تصدير تقارير مفصّلة باختيار الأقسام والمدة */
const EXPORT_PARTS = [
  ['tickets', 'البلاغات بالتفصيل', 'ticket'],
  ['ticketsAgg', 'إحصاء البلاغات (الإدارات، الفئات، الأجهزة)', 'chart'],
  ['chat', 'الاستفسارات (إحصاء بلا محتوى)', 'bell'],
  ['inventory', 'المخزن والأرصدة', 'warehouse'],
  ['movements', 'حركات المخزون', 'swap'],
  ['custody', 'عهد الإدارات', 'building'],
  ['maint', 'الصيانة والخارج عن الخدمة', 'tools'],
  ['vouchers', 'السندات الصادرة', 'file']
];
Pages.exportModal = () => UI.modal({
  title: 'تصدير تقرير مفصّل', icon: 'download', size: 'lg',
  body: html`<p class="muted" style="margin-bottom:10px">اختر المدة والأقسام المطلوبة، ويُصدَّر ملف Excel بورقة لكل قسم.</p>
    <div class="range-bar mb"><span class="faint small">من</span><input type="date" id="exFrom" dir="ltr" lang="en-GB" value="${dateInput(now() - 30 * DAY)}"><span class="faint small">إلى</span><input type="date" id="exTo" dir="ltr" lang="en-GB" value="${dateInput(now())}"></div>
    <div class="chip-pick">${EXPORT_PARTS.map(([k, l, ic]) => html`<label><input type="checkbox" data-part="${k}"${['tickets', 'ticketsAgg'].includes(k) ? raw(' checked') : ''}><span>${UI.icon(ic)} ${l}</span></label>`)}</div>`,
  actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'تصدير Excel', kind: 'primary', icon: 'download', submit: true, handler: async (form) => {
    const parts = $$('[data-part]:checked', form).map((x) => x.dataset.part);
    if (!parts.length) throw new AppError('اختر قسماً واحداً على الأقل');
    const from = startOfDay(fromDateInput(form.querySelector('#exFrom').value, true));
    const to = startOfDay(fromDateInput(form.querySelector('#exTo').value, true)) + DAY - 1;
    const book = [];
    const tickets = (await DB.getAll('tickets')).filter((t) => t.createdAt >= from && t.createdAt <= to);
    const items = new Map((await DB.getAll('items')).map((i) => [i.id, i]));
    if (parts.includes('tickets')) book.push({ name: 'البلاغات', widths: [16, 40, 18, 12, 14, 22, 20, 20, 20], rows: [['رقم البلاغ', 'العنوان', 'الفئة', 'الأولوية', 'الحالة', 'الإدارة', 'المسؤول', 'تاريخ الفتح', 'تاريخ الإغلاق'], ...tickets.map((t) => [t.number, t.title, Data.nameOf('categories', t.categoryId, ''), (PRIORITY[t.priority] || {}).label || '', (STATUS[t.status] || {}).label || '', Data.nameOf('departments', t.departmentId, ''), t.assigneeId ? Data.userName(t.assigneeId) : '', fmtDateTime(t.createdAt), t.closedAt ? fmtDateTime(t.closedAt) : ''])] });
    if (parts.includes('ticketsAgg')) {
      const agg = (keyFn, nameFn) => { const m = new Map(); tickets.forEach((t) => { const k = keyFn(t); m.set(k, (m.get(k) || 0) + 1); }); return [...m].sort((a, b) => b[1] - a[1]).map(([k, v]) => [nameFn(k), String(v)]); };
      book.push({ name: 'إحصاء الإدارات', widths: [30, 14], rows: [['الإدارة', 'عدد البلاغات'], ...agg((t) => t.departmentId, (k) => Data.nameOf('departments', k, 'غير محدد'))] });
      book.push({ name: 'إحصاء الفئات', widths: [30, 14], rows: [['الفئة', 'عدد البلاغات'], ...agg((t) => t.categoryId, (k) => Data.nameOf('categories', k, 'غير محدد'))] });
      book.push({ name: 'إحصاء الحالات', widths: [24, 14], rows: [['الحالة', 'عدد البلاغات'], ...agg((t) => t.status, (k) => (STATUS[k] || {}).label || k)] });
      book.push({ name: 'إحصاء الفنيين', widths: [26, 14], rows: [['الفني', 'عدد البلاغات'], ...agg((t) => t.assigneeId || '—', (k) => (k === '—' ? 'غير مسند' : Data.userName(k)))] });
      const dev = new Map(); tickets.forEach((t) => { const f = ((t.extra || {}).fields || []); const b = (f.find((x) => x.key === 'brand') || {}).value || ''; const d = (f.find((x) => x.key === 'device') || {}).value || Data.nameOf('categories', t.categoryId, ''); const k = [d, b].filter(Boolean).join(' — '); dev.set(k, (dev.get(k) || 0) + 1); });
      book.push({ name: 'إحصاء الأجهزة', widths: [34, 14], rows: [['نوع الجهاز أو الماركة', 'عدد البلاغات'], ...[...dev].sort((a, b) => b[1] - a[1]).map(([k, v]) => [k, String(v)])] });
    }
    if (parts.includes('chat')) {
      const chats = (await DB.getAll('chats')).filter((c) => c.createdAt >= from && c.createdAt <= to);
      const byDep = new Map(), byUser = new Map();
      chats.forEach((c) => { byDep.set(c.departmentId, (byDep.get(c.departmentId) || 0) + 1); byUser.set(c.userId, (byUser.get(c.userId) || 0) + 1); });
      book.push({ name: 'الاستفسارات', widths: [30, 16, 16], rows: [['الإدارة', 'عدد الاستفسارات', 'الحالة'], ...[...byDep].sort((a, b) => b[1] - a[1]).map(([k, v]) => [Data.nameOf('departments', k, 'غير محدد'), String(v), '']), [''], ['أكثر المستفيدين', 'العدد', ''], ...[...byUser].sort((a, b) => b[1] - a[1]).slice(0, 20).map(([k, v]) => [Data.userName(k), String(v), ''])] });
    }
    if (parts.includes('inventory')) book.push({ name: 'المخزن', widths: [34, 16, 20, 12, 12], rows: [['الصنف', 'الرمز', 'التصنيف', 'الرصيد', 'الحد الأدنى'], ...[...items.values()].map((i) => [i.name, i.sku || '', Data.nameOf('itemCategories', i.categoryId, ''), String(i.onHand), String(i.minQty || 0)])] });
    if (parts.includes('movements')) { const mv = (await DB.getAll('movements')).filter((m) => m.at >= from && m.at <= to); book.push({ name: 'الحركات', widths: [20, 30, 12, 20, 22, 18], rows: [['النوع', 'الصنف', 'الكمية', 'المخزن', 'الإدارة', 'التاريخ'], ...mv.map((m) => [(MOVES[m.type] || {}).label || m.type, (items.get(m.itemId) || {}).name || '', String(m.qty), Data.nameOf('warehouses', m.warehouseId, ''), Data.nameOf('departments', m.departmentId, ''), fmtDateTime(m.at)])] }); }
    if (parts.includes('custody')) { const ds = (await DB.getAll('deptStock')).filter((d) => d.qty > 0); book.push({ name: 'عهد الإدارات', widths: [28, 34, 12], rows: [['الإدارة', 'الصنف', 'الكمية'], ...ds.map((d) => [Data.nameOf('departments', d.departmentId, ''), (items.get(d.itemId) || {}).name || '', String(d.qty)])] }); }
    if (parts.includes('maint')) { const mt = (await DB.getAll('maintenance')).filter((m) => m.openedAt >= from && m.openedAt <= to); book.push({ name: 'الصيانة', widths: [30, 18, 22, 22, 18, 30, 16], rows: [['الجهاز', 'الرقم التسلسلي', 'الإدارة', 'السبب', 'الحالة', 'ما تم', 'التاريخ'], ...mt.map((m) => [m.itemName, m.serial || '', Data.nameOf('departments', m.fromDepartmentId, ''), m.reason, (MAINT_STATUS[m.status] || {}).label || m.status, m.workDone || '', fmtDate(m.openedAt)])] }); }
    if (parts.includes('vouchers')) { const vs = (await DB.getAll('vouchers')).filter((v) => v.at >= from && v.at <= to); book.push({ name: 'السندات', widths: [18, 16, 24, 24, 12, 18], rows: [['رقم السند', 'النوع', 'المستلم', 'الإدارة', 'الوحدات', 'التاريخ'], ...vs.map((v) => [v.number, (VOUCHER_KIND[v.type] || {}).label || v.type, v.holder || '', Data.nameOf('departments', v.departmentId, ''), String(v.units || 0), fmtDateTime(v.at)])] }); }
    downloadBlob(XL.write(book), `تقرير-مفصل-${dateInput(from)}_${dateInput(to)}.xlsx`);
    UI.toast(`تم تصدير ${arCount(book.length, AR.item).replace('صنف', 'ورقة').replace('أصناف', 'أوراق')}`);
    return true;
  } }]
});

/* ── الصيانة والأجهزة الخارجة عن الخدمة ── */
const MAINT_STATUS = {
  open: { label: 'تحت الصيانة', tone: 'sky', icon: 'tools' },
  done: { label: 'انتهت الصيانة — بانتظار الإرجاع', tone: 'teal', icon: 'check' },
  returned: { label: 'أُرجع إلى الموقع', tone: 'green', icon: 'undo' },
  retired: { label: 'مشطوب (تالف)', tone: 'red', icon: 'x' }
};
const MAINT_REASONS = ['عطل في التشغيل', 'بطء أو تعليق', 'عطل في الشاشة', 'عطل في الطاقة', 'عطل في الطباعة', 'تلف مادي', 'صيانة دورية', 'سبب آخر'];
const RETIRE_REASONS = ['تلف لا يمكن إصلاحه', 'تقادم وانتهاء العمر التشغيلي', 'فقدان', 'استبدال بجهاز أحدث', 'سبب آخر'];
Data.maint = {
  list: () => DB.getAll('maintenance'),
  async byAsset(assetId) { return (await DB.getAll('maintenance', 'assetId', KR(assetId))).sort((a, b) => b.openedAt - a.openedAt); },
  async byItem(itemId) { return (await DB.getAll('maintenance', 'itemId', KR(itemId))).sort((a, b) => b.openedAt - a.openedAt); },
  async send({ itemId, assetId = '', departmentId = '', unitId = '', reason, symptom = '', ticketId = '' }) {
    const item = await DB.get('items', itemId); if (!item) throw new AppError('الصنف غير موجود');
    const asset = assetId ? await DB.get('assets', assetId) : null;
    const t = now();
    if (departmentId) {
      const ds = await DB.get('deptStock', [departmentId, itemId]);
      if (!ds || ds.qty < 1) throw new AppError('هذا الصنف غير مسجل في عهدة الإدارة المحددة');
      ds.qty -= 1; ds.updatedAt = t; await DB.put('deptStock', ds);
      if (unitId) { const us = await DB.get('unitStock', [unitId, itemId]); if (us && us.qty > 0) { us.qty -= 1; us.updatedAt = t; await DB.put('unitStock', us); } }
    }
    if (asset) { asset.status = 'maintenance'; asset.departmentId = ''; asset.holder = ''; asset.holderId = ''; asset.updatedAt = t; await DB.put('assets', asset); }
    const rec = { id: uid('mt'), itemId, assetId, serial: asset ? asset.serial : '', tag: asset ? asset.tag || '' : '', itemName: item.name, brand: item.brand || '', model: item.model || '', fromDepartmentId: departmentId, fromUnitId: unitId, reason, symptom, ticketId, status: 'open', openedAt: t, openedBy: Auth.user.id, workDone: '', parts: '', cost: '', closedAt: 0, closedBy: '', returnedAt: 0, returnedBy: '', toDepartmentId: '', toUnitId: '' };
    await DB.put('maintenance', rec);
    await Data.log('update', 'inventory', itemId, `إرسال ${item.name}${rec.serial ? ` (${rec.serial})` : ''} إلى الصيانة — ${reason}`);
    const managers = Data.list('users').filter((u) => u.active && canUser(u, 'inventory.move')).map((u) => u.id);
    if (managers.length) await Data.notify(managers, { title: `جهاز في الصيانة: ${item.name}`, body: `${reason}${departmentId ? ` — من ${Data.nameOf('departments', departmentId)}` : ''}`, link: '/maintenance', kind: 'inventory' });
    Bus.emit('inventory', {});
    return rec;
  },
  async complete(id, { workDone, parts = '', result = 'repaired', retireReason = '' }) {
    const rec = await DB.get('maintenance', id); if (!rec) throw new AppError('السجل غير موجود');
    if (!String(workDone || '').trim()) throw new AppError('اكتب ما تم في الصيانة');
    rec.workDone = String(workDone).trim(); rec.parts = parts; delete rec.cost; rec.closedAt = now(); rec.closedBy = Auth.user.id;
    if (result === 'retired') { rec.status = 'retired'; rec.retireReason = retireReason || 'تلف لا يمكن إصلاحه'; if (rec.assetId) await Data.maint.markRetired(rec.assetId, rec.retireReason, rec.fromDepartmentId); }
    else rec.status = 'done';
    await DB.put('maintenance', rec);
    await Data.log('update', 'inventory', rec.itemId, `${result === 'retired' ? 'شطب بعد الصيانة' : 'انتهت صيانة'} ${rec.itemName}${rec.serial ? ` (${rec.serial})` : ''}`);
    Bus.emit('inventory', {});
    return rec;
  },
  async markRetired(assetId, reason, fromDepartmentId = '', replacedBy = '') {
    const a = await DB.get('assets', assetId); if (!a) return null;
    a.status = 'retired'; a.retiredAt = now(); a.retireReason = reason; a.retiredFrom = fromDepartmentId || a.departmentId || ''; a.replacedBy = replacedBy; a.departmentId = ''; a.holder = ''; a.holderId = ''; a.warehouseId = ''; a.updatedAt = now();
    await DB.put('assets', a); Bus.emit('inventory', {});
    return a;
  },
  async back(id, { departmentId, unitId = '' }) {
    const rec = await DB.get('maintenance', id); if (!rec) throw new AppError('السجل غير موجود');
    if (!departmentId) throw new AppError('اختر الإدارة المستلمة');
    const t = now();
    const ds = (await DB.get('deptStock', [departmentId, rec.itemId])) || { departmentId, itemId: rec.itemId, qty: 0 };
    ds.qty += 1; ds.updatedAt = t; await DB.put('deptStock', ds);
    if (unitId) await Data.units.add(unitId, departmentId, rec.itemId, 1);
    if (rec.assetId) { const a = await DB.get('assets', rec.assetId); if (a) { a.status = 'issued'; a.departmentId = departmentId; a.updatedAt = t; await DB.put('assets', a); } }
    rec.status = 'returned'; rec.returnedAt = t; rec.returnedBy = Auth.user.id; rec.toDepartmentId = departmentId; rec.toUnitId = unitId;
    await DB.put('maintenance', rec);
    await Data.log('move', 'inventory', rec.itemId, `إرجاع ${rec.itemName} بعد الصيانة إلى ${Data.nameOf('departments', departmentId)}`);
    Bus.emit('inventory', {});
    return rec;
  }
};

/* نوافذ الصيانة والشطب */
Pages.maintSendModal = async (itemId, scope = {}) => {
  const item = await DB.get('items', itemId); if (!item) return false;
  const assets = (await Data.assets.byItem(itemId)).filter((a) => ['issued', 'in_store', 'loaned'].includes(a.status) && (!scope.departmentId || a.departmentId === scope.departmentId || a.status === 'in_store'));
  const tree = scope.departmentId ? await Data.units.tree(scope.departmentId) : [];
  const offices = tree.flatMap((s) => s.offices.map((o) => ({ value: o.id, label: `${s.name} — ${o.name}` })));
  return UI.modal({
    title: `إرسال ${item.name} إلى الصيانة`, icon: 'tools', size: 'lg',
    body: html`<div class="banner tone-sky">${UI.icon('info')}<div class="grow">يخرج الجهاز من عهدة الإدارة ويُسجَّل تحت الصيانة، ويمكن متابعته وإرجاعه بعد الإصلاح.</div></div>
      <div class="form-grid mt">
        ${UI.field({ name: 'departmentId', label: 'من إدارة', type: 'select', options: UI.opts('departments') }, scope.departmentId || '')}
        ${offices.length ? UI.field({ name: 'unitId', label: 'من مكتب', type: 'select', options: offices }, scope.unitId || '') : ''}
        ${assets.length ? UI.field({ name: 'assetId', label: 'الوحدة (الرقم التسلسلي)', type: 'select', options: assets.map((a) => ({ value: a.id, label: `${a.serial}${a.tag ? ` — أصل ${a.tag}` : ''}` })) }) : ''}
        ${UI.field({ name: 'reason', label: 'سبب الإرسال', type: 'select', placeholder: false, options: MAINT_REASONS.map((r) => ({ value: r, label: r })) })}
        ${UI.field({ name: 'symptom', label: 'وصف العطل كما ظهر', type: 'textarea', rows: 3, wide: true, placeholder: 'ما الذي لاحظته؟ متى يحدث؟' })}
      </div>`,
    actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'إرسال إلى الصيانة', kind: 'primary', icon: 'tools', submit: true, handler: async (form) => {
      const v = UI.formValues(form);
      const rec = await Data.maint.send({ itemId, assetId: v.assetId || '', departmentId: v.departmentId || '', unitId: v.unitId || '', reason: v.reason, symptom: v.symptom });
      UI.toast('سُجّل الجهاز تحت الصيانة'); UI.sound('success'); return rec;
    } }]
  });
};
Pages.maintDoneModal = (rec) => UI.modal({
  title: `إنهاء صيانة ${rec.itemName}`, icon: 'check', size: 'lg',
  body: html`<dl class="kv"><dt>الجهاز</dt><dd>${rec.itemName} ${[rec.brand, rec.model].filter(Boolean).join(' ')}</dd><dt>الرقم التسلسلي</dt><dd class="ltr">${rec.serial || '—'}</dd><dt>سبب الإرسال</dt><dd>${rec.reason}</dd><dt>الوصف</dt><dd>${rec.symptom || '—'}</dd></dl>
    <div class="form-grid mt">
      ${UI.field({ name: 'workDone', label: 'ما تم في الصيانة', type: 'textarea', rows: 3, required: true, wide: true, placeholder: 'مثال: استبدال مزود الطاقة وتنظيف داخلي وتحديث التعريفات' })}
      ${UI.field({ name: 'parts', label: 'القطع المستخدمة', placeholder: 'مثال: مزود طاقة 500W' })}
      ${UI.field({ name: 'result', label: 'النتيجة', type: 'select', placeholder: false, options: [{ value: 'repaired', label: 'تم الإصلاح ويعمل' }, { value: 'retired', label: 'تعذر الإصلاح — شطب الجهاز' }] })}
      ${UI.field({ name: 'retireReason', label: 'سبب الشطب (عند تعذر الإصلاح)', type: 'select', options: RETIRE_REASONS.map((r) => ({ value: r, label: r })), wide: true })}
    </div>`,
  actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'حفظ نتيجة الصيانة', kind: 'primary', icon: 'check', submit: true, handler: async (form) => { const v = UI.formValues(form); const out = await Data.maint.complete(rec.id, v); UI.toast(v.result === 'retired' ? 'سُجّل الجهاز مشطوباً' : 'سُجّلت نتيجة الصيانة'); return out; } }]
});
Pages.maintBackModal = async (rec) => {
  const dep = rec.fromDepartmentId || '';
  const tree = dep ? await Data.units.tree(dep) : [];
  const offices = tree.flatMap((s) => s.offices.map((o) => ({ value: o.id, label: `${s.name} — ${o.name}` })));
  return UI.modal({
    title: `إرجاع ${rec.itemName} إلى الموقع`, icon: 'undo', size: 'lg',
    body: html`<p class="muted" style="margin-bottom:10px">يعود الجهاز إلى عهدة الإدارة ويُسجَّل تاريخ الإرجاع في سجله.</p>
      <div class="form-grid">${UI.fields([{ name: 'departmentId', label: 'إلى إدارة', type: 'select', options: UI.opts('departments'), value: dep, required: true }, { name: 'unitId', label: 'إلى مكتب', type: 'select', options: offices, value: rec.fromUnitId || '' }])}</div>`,
    actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'تأكيد الإرجاع', kind: 'ok', icon: 'check', submit: true, handler: async (form) => { const v = UI.formValues(form); const out = await Data.maint.back(rec.id, { departmentId: v.departmentId, unitId: v.unitId }); UI.toast('أُرجع الجهاز إلى الموقع'); return out; } }]
  });
};
Pages.retireModal = async (itemId, scope = {}) => {
  const item = await DB.get('items', itemId);
  const assets = (await Data.assets.byItem(itemId)).filter((a) => a.status !== 'retired');
  return UI.modal({
    title: `شطب ${item ? item.name : 'جهاز'}`, icon: 'x', size: 'lg',
    body: html`<div class="banner tone-red">${UI.icon('alert')}<div class="grow">الجهاز المشطوب يخرج من أرصدة المخزن والعهد ويُحفظ في سجل الأجهزة الخارجة عن الخدمة.</div></div>
      <div class="form-grid mt">
        ${assets.length ? UI.field({ name: 'assetId', label: 'الوحدة', type: 'select', options: assets.map((a) => ({ value: a.id, label: `${a.serial}${a.tag ? ` — ${a.tag}` : ''} (${ASSET_STATUS[a.status].label})` })), required: true }) : ''}
        ${UI.field({ name: 'reason', label: 'سبب الشطب', type: 'select', placeholder: false, options: RETIRE_REASONS.map((r) => ({ value: r, label: r })) })}
        ${UI.field({ name: 'replacedBy', label: 'الجهاز البديل إن وُجد', placeholder: 'اسم الجهاز أو رقمه التسلسلي' })}
        ${UI.field({ name: 'notes', label: 'ملاحظات', type: 'textarea', rows: 2, wide: true })}
      </div>`,
    actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'تأكيد الشطب', kind: 'danger', icon: 'x', submit: true, handler: async (form) => {
      const v = UI.formValues(form);
      if (!v.assetId) throw new AppError('اختر الوحدة المطلوب شطبها');
      const a = await DB.get('assets', v.assetId);
      const dep = a ? a.departmentId : scope.departmentId || '';
      if (dep) { const ds = await DB.get('deptStock', [dep, itemId]); if (ds && ds.qty > 0) { ds.qty -= 1; ds.updatedAt = now(); await DB.put('deptStock', ds); } }
      if (a && a.status === 'in_store' && a.warehouseId) { const st = await DB.get('stock', [a.warehouseId, itemId]); await Data.inv.move({ type: 'adjust', itemId, warehouseId: a.warehouseId, qty: Math.max(0, ((st || {}).qty || 0) - 1), note: `شطب: ${v.reason}` }); }
      await Data.maint.markRetired(v.assetId, v.reason, dep, v.replacedBy);
      await DB.put('maintenance', { id: uid('mt'), itemId, assetId: v.assetId, serial: a ? a.serial : '', tag: a ? a.tag || '' : '', itemName: item.name, brand: item.brand || '', model: item.model || '', fromDepartmentId: dep, fromUnitId: '', reason: v.reason, symptom: v.notes || '', status: 'retired', retireReason: v.reason, replacedBy: v.replacedBy || '', openedAt: now(), openedBy: Auth.user.id, workDone: '', parts: '', cost: '', closedAt: now(), closedBy: Auth.user.id, returnedAt: 0, returnedBy: '' });
      await Data.log('delete', 'inventory', itemId, `شطب ${item.name}${a ? ` (${a.serial})` : ''} — ${v.reason}`);
      Bus.emit('inventory', {});
      UI.toast('سُجّل الجهاز في سجل الخارج عن الخدمة'); return true;
    } }]
  });
};

/* صفحة الصيانة */
Pages.maintenance = async (ctx) => {
  const st = { tab: 'open', q: '', from: '', to: '' };
  const draw = async () => {
    const all = (await Data.maint.list()).sort((a, b) => b.openedAt - a.openedAt);
    if (!ctx.alive()) return;
    const inRange = (r) => { const f = st.from ? startOfDay(fromDateInput(st.from, true)) : 0, t = st.to ? startOfDay(fromDateInput(st.to, true)) + DAY - 1 : Infinity; return r.openedAt >= f && r.openedAt <= t; };
    const qn = normalizeAr(st.q);
    const rows = all.filter((r) => (st.tab === 'all' || r.status === st.tab) && inRange(r) && (!qn || normalizeAr(`${r.itemName} ${r.serial} ${r.tag} ${r.reason} ${r.workDone} ${Data.nameOf('departments', r.fromDepartmentId, '')}`).includes(qn)));
    const count = (s) => all.filter((r) => r.status === s).length;
    ctx.view.innerHTML = String(html`
      ${UI.pageHead({ title: 'الصيانة', sub: 'الأجهزة المرسلة للصيانة وما تم فيها وإرجاعها إلى مواقعها', illu: 'tools', actions: html`${Auth.can('inventory.move') ? html`<button class="btn btn-primary" data-act="send">${UI.icon('tools')} إرسال جهاز للصيانة</button>` : ''}<a class="btn btn-ghost" href="#/inventory/retired">${UI.icon('x')} الخارج عن الخدمة</a><button class="btn btn-ghost" data-act="xls">${UI.icon('download')} تصدير</button>` })}
      <div class="kpis">
        ${UI.kpi({ label: 'تحت الصيانة', icon: 'tools', tone: 'sky', value: count('open') })}
        ${UI.kpi({ label: 'بانتظار الإرجاع', icon: 'check', tone: 'teal', value: count('done') })}
        ${UI.kpi({ label: 'أُرجعت للمواقع', icon: 'undo', tone: 'green', value: count('returned') })}
        ${UI.kpi({ label: 'مشطوبة', icon: 'x', tone: 'red', value: count('retired') })}
      </div>
      <section class="panel mt"><div class="toolbar">
        <div class="tabs">${[['open', 'تحت الصيانة'], ['done', 'بانتظار الإرجاع'], ['returned', 'مكتملة'], ['retired', 'مشطوبة'], ['all', 'الكل']].map(([k, l]) => html`<button class="tab${st.tab === k ? ' active' : ''}" data-tab="${k}">${l}</button>`)}</div>
        <div class="search-box">${UI.icon('search')}<input id="mq" type="search" placeholder="الجهاز أو الرقم التسلسلي أو الإدارة" value="${st.q}"></div>
        <div class="range-bar"><span class="faint small">من</span><input type="date" id="mFrom" dir="ltr" lang="en-GB" value="${st.from}"><span class="faint small">إلى</span><input type="date" id="mTo" dir="ltr" lang="en-GB" value="${st.to}"></div>
      </div>
      ${rows.length ? html`<div class="table-wrap"><table class="table"><thead><tr><th>الجهاز</th><th>الرقم التسلسلي</th><th>من</th><th>السبب</th><th>الحالة</th><th>التاريخ</th><th></th></tr></thead><tbody class="stagger">${rows.slice(0, 200).map((r) => html`<tr><td><button type="button" class="t-title link-title" data-device="${r.itemId}"><div><div>${r.itemName}</div><div class="t-sub">${[r.brand, r.model].filter(Boolean).join(' ')}</div></div></button></td><td class="t-num ltr">${r.serial || '—'}${r.tag ? html`<div class="t-sub ltr" style="text-align:start">أصل: ${r.tag}</div>` : ''}</td><td class="small">${Data.nameOf('departments', r.fromDepartmentId, '—')}</td><td class="small">${r.reason}</td><td>${UI.chip(MAINT_STATUS[r.status].tone, MAINT_STATUS[r.status].label, MAINT_STATUS[r.status].icon)}</td><td class="faint nowrap">${fmtDate(r.openedAt)}</td><td class="nowrap">${Auth.can('inventory.move') ? html`${r.status === 'open' ? html`<button class="btn btn-sm btn-ok" data-done="${r.id}">${UI.icon('check')} إنهاء الصيانة</button>` : ''}${r.status === 'done' ? html`<button class="btn btn-sm btn-primary" data-back="${r.id}">${UI.icon('undo')} إرجاع للموقع</button>` : ''}` : ''}<button class="btn btn-ghost btn-sm" data-print="${r.id}">${UI.icon('print')}</button></td></tr>`)}</tbody></table></div>`
        : html`<div class="panel-body">${UI.empty({ illu: 'tools', title: 'لا توجد سجلات صيانة', text: 'أرسل جهازاً للصيانة من صفحة العهدة أو من بطاقة الجهاز.' })}</div>`}</section>`);
    UI.hydrate(ctx.view);
    ctx.rows = rows;
    $('#mq', ctx.view).addEventListener('input', debounce((e) => { st.q = e.target.value.trim(); draw(); }, 250));
    ['mFrom', 'mTo'].forEach((id) => { const el = $('#' + id, ctx.view); if (el) el.onchange = () => { st[id === 'mFrom' ? 'from' : 'to'] = el.value; draw(); }; });
  };
  UI.on(ctx.view, 'click', '[data-tab]', (e, el) => { st.tab = el.dataset.tab; draw(); });
  UI.on(ctx.view, 'click', '[data-device]', async (e, el) => { await Pages.deviceModal(el.dataset.device, {}); });
  UI.on(ctx.view, 'click', '[data-done]', async (e, el) => { const r = await DB.get('maintenance', el.dataset.done); if (r && (await Pages.maintDoneModal(r))) { st.tab = 'done'; draw(); } });
  UI.on(ctx.view, 'click', '[data-back]', async (e, el) => { const r = await DB.get('maintenance', el.dataset.back); if (r && (await Pages.maintBackModal(r))) draw(); });
  UI.on(ctx.view, 'click', '[data-print]', async (e, el) => { const r = await DB.get('maintenance', el.dataset.print); if (r) Pages.printMaint(r); });
  UI.on(ctx.view, 'click', '[data-act="send"]', async () => { const id = await Pages.pickItemModal('اختر الجهاز المطلوب إرساله للصيانة'); if (id && (await Pages.maintSendModal(id, {}))) draw(); });
  UI.on(ctx.view, 'click', '[data-act="xls"]', () => {
    const rows = ctx.rows || [];
    downloadBlob(XL.write([{ name: 'الصيانة', widths: [30, 18, 20, 22, 18, 30, 18, 16], rows: [['الجهاز', 'الرقم التسلسلي', 'الإدارة', 'السبب', 'الحالة', 'ما تم في الصيانة', 'القطع', 'التاريخ'], ...rows.map((r) => [r.itemName, r.serial || '', Data.nameOf('departments', r.fromDepartmentId, ''), r.reason, MAINT_STATUS[r.status].label, r.workDone || '', r.parts || '', fmtDate(r.openedAt)])] }]), `تقرير-الصيانة-${dateInput(now())}.xlsx`);
    UI.toast('تم التصدير');
  });
  Pages.bindInv(ctx, draw);
  await draw();
};
Pages.printMaint = (r) => UI.print(html`<h2 style="text-align:center">سند صيانة جهاز</h2>
  <table><tr><th>الجهاز</th><td>${r.itemName}</td><th>الماركة والموديل</th><td>${[r.brand, r.model].filter(Boolean).join(' ') || '—'}</td></tr>
    <tr><th>الرقم التسلسلي</th><td class="ltr">${r.serial || '—'}</td><th>رقم الأصل</th><td class="ltr">${r.tag || '—'}</td></tr>
    <tr><th>الإدارة</th><td>${Data.nameOf('departments', r.fromDepartmentId, '—')}</td><th>تاريخ الإرسال</th><td>${fmtDateTime(r.openedAt)}</td></tr>
    <tr><th>سبب الإرسال</th><td>${r.reason}</td><th>الحالة</th><td>${MAINT_STATUS[r.status].label}</td></tr>
    <tr><th>أرسله للصيانة</th><td>${who(r.openedBy)}</td><th>الفني المنفذ</th><td>${r.closedBy ? who(r.closedBy) : '—'}</td></tr>
    <tr><th>وصف العطل</th><td colspan="3">${r.symptom || '—'}</td></tr>
    <tr><th>ما تم في الصيانة</th><td colspan="3">${r.workDone || '—'}</td></tr>
    <tr><th>القطع المستخدمة</th><td colspan="3">${r.parts || '—'}</td></tr>
    ${r.returnedAt ? html`<tr><th>تاريخ الإرجاع</th><td>${fmtDateTime(r.returnedAt)}</td><th>أُرجع إلى</th><td>${Data.nameOf('departments', r.toDepartmentId, '—')}</td></tr>` : ''}</table>
  ${UI.signBlock([{ title: 'الفني المنفّذ للصيانة', userId: r.closedBy || r.openedBy }, { title: 'مستلم الجهاز' }])}`, `سند صيانة ${r.itemName}`);

/* سجل الأجهزة الخارجة عن الخدمة */
Pages.retired = async (ctx) => {
  const st = { q: '', from: '', to: '' };
  const draw = async () => {
    const assets = (await DB.getAll('assets')).filter((a) => a.status === 'retired');
    const maint = await Data.maint.list();
    if (!ctx.alive()) return;
    const info = new Map(maint.filter((m) => m.status === 'retired').map((m) => [m.assetId, m]));
    const items = new Map((await DB.getAll('items')).map((i) => [i.id, i]));
    const qn = normalizeAr(st.q);
    const rows = assets.filter((a) => {
      const f = st.from ? startOfDay(fromDateInput(st.from, true)) : 0, t = st.to ? startOfDay(fromDateInput(st.to, true)) + DAY - 1 : Infinity;
      const at = a.retiredAt || a.updatedAt || 0;
      return at >= f && at <= t && (!qn || normalizeAr(`${a.serial} ${a.tag || ''} ${(items.get(a.itemId) || {}).name || ''} ${a.retireReason || ''} ${Data.nameOf('departments', a.retiredFrom, '')}`).includes(qn));
    }).sort((a, b) => (b.retiredAt || 0) - (a.retiredAt || 0));
    ctx.view.innerHTML = String(html`
      ${UI.pageHead({ title: 'الأجهزة الخارجة عن الخدمة', sub: 'الأجهزة المشطوبة أو التالفة، لا تُحتسب ضمن أرصدة المخزن ولا عهد الإدارات', illu: 'box', actions: html`<a class="btn btn-ghost" href="#/maintenance">${UI.icon('tools')} الصيانة</a><button class="btn btn-ghost" data-act="xls">${UI.icon('download')} تصدير</button>` })}
      <div class="kpis">${UI.kpi({ label: 'إجمالي المشطوبة', icon: 'x', tone: 'red', value: assets.length })}${UI.kpi({ label: 'خلال 90 يوماً', icon: 'clock', tone: 'amber', value: assets.filter((a) => now() - (a.retiredAt || 0) < 90 * DAY).length })}${UI.kpi({ label: 'إدارات متأثرة', icon: 'building', tone: 'violet', value: new Set(assets.map((a) => a.retiredFrom).filter(Boolean)).size })}</div>
      <section class="panel mt"><div class="toolbar"><div class="search-box">${UI.icon('search')}<input id="rq" type="search" placeholder="الرقم التسلسلي أو الجهاز أو السبب" value="${st.q}"></div><div class="range-bar"><span class="faint small">من</span><input type="date" id="rFrom" dir="ltr" lang="en-GB" value="${st.from}"><span class="faint small">إلى</span><input type="date" id="rTo" dir="ltr" lang="en-GB" value="${st.to}"></div></div>
      ${rows.length ? html`<div class="table-wrap"><table class="table"><thead><tr><th>الجهاز</th><th>الرقم التسلسلي</th><th>سبب الشطب</th><th>كان في</th><th>البديل</th><th>التاريخ</th></tr></thead><tbody class="stagger">${rows.slice(0, 200).map((a) => { const it = items.get(a.itemId) || {}, m = info.get(a.id) || {}; return html`<tr><td><button type="button" class="t-title link-title" data-device="${a.itemId}">${UI.illu(itemIllu(it))}<div><div>${it.name || 'صنف محذوف'}</div><div class="t-sub">${[it.brand, it.model].filter(Boolean).join(' ')}</div></div></button></td><td class="t-num ltr">${a.serial}${a.tag ? html`<div class="t-sub ltr" style="text-align:start">أصل: ${a.tag}</div>` : ''}</td><td class="small">${a.retireReason || m.retireReason || '—'}</td><td class="small">${Data.nameOf('departments', a.retiredFrom, '—')}</td><td class="small">${a.replacedBy || '—'}</td><td class="faint nowrap">${a.retiredAt ? fmtDate(a.retiredAt) : '—'}</td></tr>`; })}</tbody></table></div>` : html`<div class="panel-body">${UI.empty({ illu: 'box', title: 'لا توجد أجهزة مشطوبة', text: 'الأجهزة التي تُشطب أو يتعذر إصلاحها تظهر هنا مع أسبابها.' })}</div>`}</section>`);
    UI.hydrate(ctx.view); ctx.rows = rows; ctx.items = items;
    $('#rq', ctx.view).addEventListener('input', debounce((e) => { st.q = e.target.value.trim(); draw(); }, 250));
    ['rFrom', 'rTo'].forEach((id) => { const el = $('#' + id, ctx.view); if (el) el.onchange = () => { st[id === 'rFrom' ? 'from' : 'to'] = el.value; draw(); }; });
  };
  UI.on(ctx.view, 'click', '[data-device]', async (e, el) => { await Pages.deviceModal(el.dataset.device, {}); });
  UI.on(ctx.view, 'click', '[data-act="xls"]', () => {
    const rows = ctx.rows || [], items = ctx.items || new Map();
    downloadBlob(XL.write([{ name: 'خارج الخدمة', widths: [30, 18, 26, 22, 22, 16], rows: [['الجهاز', 'الرقم التسلسلي', 'سبب الشطب', 'كان في', 'البديل', 'التاريخ'], ...rows.map((a) => { const it = items.get(a.itemId) || {}; return [it.name || '', a.serial, a.retireReason || '', Data.nameOf('departments', a.retiredFrom, ''), a.replacedBy || '', a.retiredAt ? fmtDate(a.retiredAt) : '']; })] }]), `الأجهزة-الخارجة-عن-الخدمة-${dateInput(now())}.xlsx`);
  });
  Pages.bindInv(ctx, draw);
  await draw();
};

/* اختيار صنف سريع */
Pages.pickItemModal = async (title = 'اختر الصنف') => {
  const items = (await DB.getAll('items')).sort((a, b) => String(a.name).localeCompare(String(b.name), 'ar'));
  return UI.modal({ title, icon: 'box', size: 'lg', body: html`${UI.field({ name: 'itemId', label: 'الصنف', type: 'select', required: true, options: items.map((i) => ({ value: i.id, label: `${i.name}${i.model ? ` — ${i.model}` : ''}` })), wide: true })}`, actions: [{ label: 'إلغاء', kind: 'ghost', value: null }, { label: 'متابعة', kind: 'primary', icon: 'check', submit: true, handler: (form) => form.querySelector('[name="itemId"]').value }] });
};

/* سجل صيانة الجهاز داخل بطاقته */
Pages.maintHistory = async (itemId, assetId = '') => {
  const rows = assetId ? await Data.maint.byAsset(assetId) : await Data.maint.byItem(itemId);
  if (!rows.length) return '';
  return html`<div class="u-sec mt"><h3>${UI.icon('tools')} سجل الصيانة (${fmtNum(rows.length)})</h3><div class="timeline">${rows.slice(0, 8).map((r) => html`<div class="tl-item"><span class="tl-icon tone-${MAINT_STATUS[r.status].tone}">${UI.icon(MAINT_STATUS[r.status].icon)}</span><div class="tl-body"><b>${r.reason}</b> — ${MAINT_STATUS[r.status].label}<div class="t-sub">${fmtDate(r.openedAt)}${r.serial ? ` — ${r.serial}` : ''}${r.fromDepartmentId ? ` — ${Data.nameOf('departments', r.fromDepartmentId)}` : ''}</div>${r.workDone ? html`<p class="muted small" style="margin:4px 0 0">${r.workDone}${r.parts ? ` — القطع: ${r.parts}` : ''}</p>` : ''}${r.returnedAt ? html`<div class="t-sub">أُرجع ${fmtDate(r.returnedAt)} إلى ${Data.nameOf('departments', r.toDepartmentId, '')}</div>` : ''}</div></div>`)}</div></div>`;
};

/* ── مكتبة النماذج والاستمارات، وأيقونات الماركات ── */
const FORM_ICONS = ['card', 'book', 'clipboard', 'paper', 'archive', 'key', 'tools', 'printer', 'computer', 'network', 'box', 'bell', 'smartcard', 'fingerprint', 'barcode', 'router'];
const canManageForms = () => canUser(Auth.user, 'users.manage') || canUser(Auth.user, 'forms.manage');
const canHideForms = () => canManageForms() || canUser(Auth.user, 'forms.hide');
Data.forms = {
  async list() { try { await this.seedBuiltin(); } catch (e) { console.warn('forms seed', e); } return (await DB.getAll('forms')).sort((a, b) => (a.order || 0) - (b.order || 0) || String(a.title).localeCompare(String(b.title), 'ar')); },
  async save(rec) {
    if (!canManageForms()) throw new AppError('لا تملك صلاحية إدارة النماذج');
    const t = now();
    const out = { id: rec.id || uid('fm'), title: String(rec.title || '').trim(), desc: String(rec.desc || '').trim(), icon: rec.icon || 'paper', categoryId: rec.categoryId || '', file: rec.file || null, order: Number(rec.order) || 0, noDownload: rec.noDownload ? 1 : 0, hidden: rec.hidden ? 1 : 0, createdAt: rec.createdAt || t, updatedAt: t, userId: rec.userId || Auth.user.id, _rev: rec._rev };
    if (!out.title) throw new AppError('اكتب اسم النموذج');
    if (!out.file) throw new AppError('ارفع ملف النموذج');
    await DB.put('forms', out);
    await Data.log('update', 'settings', out.id, `${rec.id ? 'تعديل' : 'إضافة'} نموذج: ${out.title}`);
    Bus.emit('forms', {});
    return out;
  },
  /* الاستمارات الرسمية المضمّنة في الملف تُضاف إلى المكتبة مرة واحدة فقط */
  /* علامة الإضافة محلية لكل جهاز: من يملك إدارة النماذج يرفعها للخادم، وغيره يضيفها لجهازه فقط حتى تصله نسخة الخادم */
  async seedBuiltin() {
    const flag = `sq_seed_forms_v2:${Auth.user ? Auth.user.id : ''}`; try { if (localStorage.getItem(flag)) return; } catch (_) { /* تجاهل */ }
    const CAT = [[/شبكة/, 'network', 'network'], [/مجلد/, 'service_request', 'folder'], [/بطاقة/, 'card', 'card']], t = now();
    const recs = await Promise.all($$('script[data-form]').map(async (el, i) => {
      const name = el.dataset.name || `استمارة ${i + 1}`, [, categoryId = '', icon = 'paper'] = CAT.find(([re]) => re.test(name)) || [];
      const b64 = el.dataset.src ? '' : el.textContent.trim();
      const data = el.dataset.src ? await fetch(el.dataset.src).then((r) => { if (!r.ok) throw new AppError('تعذر تحميل الاستمارة'); return r.blob(); }).then((b) => blobToDataURL(new Blob([b], { type: 'application/pdf' }))) : `data:application/pdf;base64,${b64}`;
      return { id: `fm_builtin_${i + 1}`, title: name, desc: 'استمارة رسمية معتمدة — للمعاينة والطباعة والتحميل', icon, categoryId, order: i, createdAt: t, updatedAt: t, file: { name: `${name}.pdf`, type: 'application/pdf', size: Number(el.dataset.size) || Math.round(b64.length * 0.75), at: t, data } };
    }));
    const local = Sync.on && Sync.raw && !canManageForms();
    for (const r of recs) {
      const cur = await DB.get('forms', r.id);
      if (!cur) await (local ? Sync.raw.put('forms', r) : DB.put('forms', r));
      else if (!local && Sync.on && !cur._rev) await DB.put('forms', cur); /* نسخة محلية لم تصل الخادم بعد */
    }
    try { localStorage.setItem(flag, String(t)); } catch (_) { /* تجاهل */ }
  },
  async remove(id) {
    if (!canManageForms()) throw new AppError('لا تملك صلاحية حذف النماذج');
    const rec = await DB.get('forms', id);
    await DB.del('forms', id);
    await Data.log('delete', 'settings', id, `حذف نموذج: ${rec ? rec.title : id}`);
    Bus.emit('forms', {});
  }
};
Pages.previewFile = (file) => {
  if (!file) return;
  const type = String(file.type || '');
  const body = type.includes('pdf') ? html`<iframe class="file-view" src="${file.data}" title="${file.name}"></iframe>`
    : type.startsWith('image/') ? html`<img class="file-view" src="${file.data}" alt="${file.name}">`
      : html`<div class="file-none">${UI.icon('file')}<b>${file.name}</b><span>هذا النوع لا يُعرض داخل النظام، حمّله لفتحه ببرنامجه.</span></div>`;
  return UI.modal({
    title: file.name, icon: 'file', size: 'xl',
    body,
    actions: [{ label: 'إغلاق', kind: 'ghost' }, { label: 'تحميل', kind: 'primary', icon: 'download', handler: () => { downloadBlob(dataToBlob(file.data), file.name); return false; } }]
  });
};
Pages.formModal = async (id = '') => {
  const rec = id ? await DB.get('forms', id) : { icon: 'paper' };
  return UI.modal({
    title: id ? `تعديل ${rec.title}` : 'نموذج جديد', icon: 'file', size: 'lg',
    body: html`${UI.fields([{ name: 'title', label: 'اسم النموذج', required: true, wide: true, placeholder: 'مثال: استمارة طلب بطاقة دخول' }, { name: 'desc', label: 'وصف مختصر', type: 'textarea', rows: 2, wide: true, placeholder: 'لمن هذا النموذج ومتى يُستخدم؟' }, { name: 'categoryId', label: 'مرتبط بفئة بلاغات (اختياري)', type: 'select', options: UI.opts('categories') }, { name: 'order', label: 'الترتيب', type: 'number', min: 0 }], rec)}
      <div class="field mt"><label>الأيقونة</label><div class="tiles sm cat-pick">${FORM_ICONS.map((k) => html`<label><input type="radio" name="icon" value="${k}"${(rec.icon || 'paper') === k ? raw(' checked') : ''}><span class="tile">${UI.illu(k)}<b>${ILLU_LABELS[k] || k}</b></span></label>`)}</div></div>
      <div class="field mt"><label for="fmFile">ملف النموذج</label>${rec.file ? html`<div class="form-bar" style="margin-bottom:8px">${UI.icon('file')}<div class="grow"><b>${rec.file.name}</b><div class="t-sub">${fmtBytes(rec.file.size)}</div></div><button type="button" class="btn btn-sm btn-soft" data-prev="${id}">${UI.icon('eye')} معاينة</button></div>` : ''}<input id="fmFile" name="file" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,image/*"><small class="hint">PDF أو Word أو صورة، بحد أقصى 3 ميجابايت.${rec.file ? ' اترك الحقل فارغاً للإبقاء على الملف الحالي.' : ''}</small></div>`,
    onMount: (form) => { UI.on(form, 'click', '[data-prev]', async () => { const r = await DB.get('forms', id); if (r && r.file) Pages.previewFile(r.file); }); },
    actions: [{ label: 'إلغاء', kind: 'ghost' }, ...(id ? [{ label: 'حذف', kind: 'danger', icon: 'trash', handler: async () => { if (!(await UI.confirm('حذف هذا النموذج نهائياً؟', { danger: true, ok: 'حذف' }))) return false; await Data.forms.remove(id); UI.toast('حُذف النموذج'); return true; } }] : []), { label: 'حفظ', kind: 'primary', icon: 'check', submit: true, handler: async (form) => {
      const v = UI.formValues(form), fi = form.querySelector('[name="file"]'), f = fi && fi.files && fi.files[0];
      let file = rec.file || null;
      if (f) { if (f.size > 3 * 1024 * 1024) throw new AppError('حجم الملف أكبر من 3 ميجابايت'); file = { name: f.name, type: f.type, size: f.size, at: now(), data: await fileToData(f) }; }
      const out = await Data.forms.save({ ...rec, ...v, id: id || undefined, file });
      UI.toast('حُفظ النموذج'); return out;
    } }]
  });
};
Pages.formsPage = async (ctx) => {
  const st = { q: '', cat: '' };
  const draw = async () => {
    const all = await Data.forms.list();
    if (!ctx.alive()) return;
    const qn = normalizeAr(st.q);
    const rows = all.filter((f) => (!f.hidden || canHideForms()) && (!st.cat || f.categoryId === st.cat) && (!qn || normalizeAr(`${f.title} ${f.desc} ${Data.nameOf('categories', f.categoryId, '')}`).includes(qn)));
    const manage = canManageForms(), hider = canHideForms();
    ctx.view.innerHTML = String(html`
      ${UI.pageHead({ title: 'النماذج والاستمارات', sub: 'استمارات جاهزة للمعاينة والتحميل والطباعة', illu: 'paper', actions: html`${manage ? html`<button class="btn btn-primary" data-act="new">${UI.icon('plus')} نموذج جديد</button>` : ''}<button class="btn btn-ghost" data-blankcard>${UI.icon('print')} استمارة بطاقة فارغة</button>` })}
      ${manage || hider ? UI.stateLegend(['off', 'lock'], { off: 'مخفي عن الموظفين', lock: 'التحميل موقوف' }) : ''}
      <section class="panel"><div class="toolbar"><div class="search-box">${UI.icon('search')}<input id="fq" type="search" placeholder="ابحث باسم النموذج" value="${st.q}"></div><select id="fcat"><option value="">كل الفئات</option>${UI.opts('categories').map((o) => html`<option value="${o.value}"${st.cat === o.value ? raw(' selected') : ''}>${o.label}</option>`)}</select><span class="faint small">${arCount(rows.length, AR.item).replace('صنف', 'نموذج').replace('أصناف', 'نماذج')}</span></div>
      ${rows.length ? html`<div class="forms-grid">${rows.map((f) => html`<article class="form-card${f.hidden ? ' off x-off' : ''}${(manage || hider) && (f.noDownload || docLocked(f.categoryId)) ? ' x-lock' : ''}">${UI.illu(f.icon || 'paper')}<div class="fc-body"><b>${f.title}</b>${f.desc ? html`<p class="t-sub">${f.desc}</p>` : ''}<div class="row" style="gap:6px;flex-wrap:wrap">${f.categoryId ? UI.chip('sky', Data.nameOf('categories', f.categoryId), 'tag') : ''}${f.file ? UI.chip('slate', fmtBytes(f.file.size)) : ''}${f.hidden ? UI.chip('red', 'مخفي عن الموظفين', 'eye-off') : ''}${(manage || hider) && (f.noDownload || docLocked(f.categoryId)) ? UI.chip('amber', 'التحميل موقوف', 'lock') : ''}</div></div>
        <div class="fc-actions">${f.categoryId && eformOn(f.categoryId) && Data.c.categories.get(f.categoryId) && !Data.c.categories.get(f.categoryId).hidden ? html`<a class="btn btn-sm btn-primary" href="#/tickets/new?cat=${f.categoryId}">${UI.icon('edit')} تعبئة إلكترونية</a>` : ''}${!manage && (f.noDownload || docLocked(f.categoryId)) ? html`<span class="chip tone-slate">${UI.icon('lock')} التحميل موقوف</span>` : html`<button class="btn btn-sm btn-soft" data-view="${f.id}">${UI.icon('eye')} معاينة</button><button class="btn btn-sm btn-soft" data-dl="${f.id}">${UI.icon('download')} تحميل</button>`}${hider ? html`<button class="btn btn-sm btn-ghost" data-hideform="${f.id}" title="${f.hidden ? 'إظهار المستند للموظفين' : 'إخفاء المستند عن الموظفين'}">${UI.icon(f.hidden ? 'eye' : 'eye-off')} ${f.hidden ? 'إظهار' : 'إخفاء'}</button>` : ''}${manage ? html`<button class="btn btn-sm btn-ghost" data-lockdl="${f.id}" title="${f.noDownload ? 'السماح بالتحميل للموظفين' : 'إيقاف التحميل للموظفين'}">${UI.icon(f.noDownload ? 'lock' : 'download')} ${f.noDownload ? 'موقوف' : 'متاح'}</button><button class="btn btn-sm btn-ghost" data-edit="${f.id}">${UI.icon('edit')}</button>` : ''}</div></article>`)}</div>`
        : html`<div class="panel-body">${UI.empty({ illu: 'paper', title: 'لا توجد نماذج بعد', text: manage ? 'أضف الاستمارات التي يحتاجها الموظفون ليحمّلوها من هنا.' : 'ستظهر هنا الاستمارات فور إضافتها من قسم تقنية المعلومات.', action: manage ? html`<button class="btn btn-primary" data-act="new">${UI.icon('plus')} نموذج جديد</button>` : '' })}</div>`}</section>`);
    UI.hydrate(ctx.view);
    $('#fq', ctx.view).addEventListener('input', debounce((e) => { st.q = e.target.value.trim(); draw(); }, 250));
    $('#fcat', ctx.view).onchange = (e) => { st.cat = e.target.value; draw(); };
  };
  UI.on(ctx.view, 'click', '[data-view]', async (e, el) => { const f = await DB.get('forms', el.dataset.view); if (f && f.file) Pages.previewFile(f.file); });
  UI.on(ctx.view, 'click', '[data-lockdl]', async (e, el) => { const f = await DB.get('forms', el.dataset.lockdl); if (!f) return; f.noDownload = f.noDownload ? 0 : 1; f.updatedAt = now(); await DB.put('forms', f); Bus.emit('forms', {}); UI.toast(f.noDownload ? `أُوقف تحميل «${f.title}» للموظفين` : `أصبح «${f.title}» متاحاً للتحميل`); draw(); });
  UI.on(ctx.view, 'click', '[data-hideform]', async (e, el) => { if (!canHideForms()) return; const f = await DB.get('forms', el.dataset.hideform); if (!f) return; f.hidden = f.hidden ? 0 : 1; f.updatedAt = now(); await DB.put('forms', f); await Data.log('update', 'settings', f.id, `${f.hidden ? 'إخفاء' : 'إظهار'} نموذج: ${f.title}`); Bus.emit('forms', {}); UI.toast(f.hidden ? `أُخفي «${f.title}» عن الموظفين` : `أصبح «${f.title}» ظاهراً للموظفين`); draw(); });
  UI.on(ctx.view, 'click', '[data-dl]', async (e, el) => { const f = await DB.get('forms', el.dataset.dl); if (f && (f.noDownload || docLocked(f.categoryId)) && !canManageForms()) { UI.toast('التحميل موقوف لهذا النموذج', 'warn'); return; } if (f && f.file) { downloadBlob(dataToBlob(f.file.data), f.file.name); UI.toast('تم التحميل'); } });
  UI.on(ctx.view, 'click', '[data-edit]', async (e, el) => { if (await Pages.formModal(el.dataset.edit)) draw(); });
  UI.on(ctx.view, 'click', '[data-act="new"]', async () => { if (await Pages.formModal()) draw(); });
  ctx.onCleanup(Bus.on('forms', debounce(() => { if (ctx.alive()) draw(); }, 400)));
  await draw();
};

