      if (!sup && ['supervisor', 'support_manager'].includes(v.role)) throw new AppError('إنشاء حسابات المشرف والإداري من صلاحية المشرف فقط');
      if (!v.departmentId) throw new AppError('اختر الإدارة');
      if (v.pwMode === 'same') Data.users.checkPolicy(v.samePw || '');
