        if (!p.name && !p.militaryNo && !p.phone) return;
        let err = '';
        if (p.name.length < 3) err = 'الاسم ناقص'; else if (!/^[\p{L}\p{N}-]{2,20}$/u.test(p.militaryNo)) err = 'الرقم العسكري ناقص أو غير صالح';
        else { const k = p.militaryNo.toLowerCase(), un = k.length < 3 ? `u${k}` : k; if (seen.has(k)) err = 'رقم عسكري مكرر في القائمة'; else if (byMil.has(k) || byUser.has(un)) err = 'يوجد حساب بهذا الرقم العسكري مسبقاً'; seen.add(k); p.username = un; }
        r.classList.toggle('bad', !!err); r.title = err;
