Pages.eFormHTML = async (t, { ef = null, blank = false, defs = null } = {}) => {
  const s = Data.c.settings, c = Data.c.categories.get(t.categoryId) || {}, form = ef || eformOf(t.categoryId) || {};
  const dots = '<span class="ef-dots"></span>', v = (x) => (blank || x == null || x === '' ? raw(dots) : x);
  const req = blank ? {} : Data.c.users.get(t.requesterId) || {}, tech = !blank && t.assigneeId ? Data.c.users.get(t.assigneeId) || {} : {};
  const evs = !blank && t.id ? await Data.tickets.events(t.id).catch(() => []) : [];
  const done = evs.filter((e) => e.type === 'status' && e.to === 'resolved').pop();
  const fields = blank ? (defs || Forms.def(t.categoryId)).map((f) => ({ label: f.l, value: '', cols: f.t === 'table' ? tableCols(f).map((x) => x.l) : null, rows: f.t === 'table' ? [[], [], []] : null })) : ((t.extra || {}).fields || []);
  const persons = blank ? [] : ((t.extra || {}).persons || []);
  const who = (u) => html`<tr><th>الرقم العسكري</th><td class="ltr">${v(u.militaryNo)}</td><th>الرتبة</th><td>${v(Data.nameOf('ranks', u.rankId, ''))}</td><th>الاسم</th><td>${v(u.name)}</td></tr>`;
  const table = (cols, rows) => html`<table class="ef-sub"><thead><tr><th>م</th>${cols.map((x) => html`<th>${x}</th>`)}</tr></thead><tbody>${rows.map((r, i) => html`<tr><td>${i + 1}</td>${cols.map((_, j) => html`<td>${r[j] || ''}</td>`)}</tr>`)}</tbody></table>`;
  return html`<div class="ef">
    <div class="ef-head"><div><b>شرطة عُمان السلطانية</b><span>${s.orgName}</span></div><img src="${ASSETS.logo}" alt=""><div><b>مركز الصيانة ودعم تقنية المعلومات والاتصالات</b><span>قسم تقنية المعلومات</span></div></div>
    <h2 class="ef-title">${form.title || `استمارة ${c.name || ''}`}</h2>
    <div class="ef-meta"><span>رقم الطلب: <b class="ltr">${blank ? '..........' : t.number}</b></span><span>التاريخ: <b>${blank ? '..........' : fmtDate(t.createdAt)}</b></span><span>الفئة: <b>${c.name || ''}</b></span></div>
    <section><h3>بيانات مقدم الطلب</h3><table class="ef-grid">${who(req)}
      <tr><th>الإدارة / القسم</th><td colspan="3">${v([Data.nameOf('departments', t.departmentId, ''), t.unitPath].filter(Boolean).join(' ← '))}</td><th>الهاتف</th><td class="ltr">${v(t.contact || req.phone)}</td></tr>
      <tr><th>الموقع</th><td colspan="3">${v([Data.nameOf('locations', t.locationId, ''), t.location].filter(Boolean).join(' — '))}</td><th>التوقيع</th><td>${blank ? raw(dots) : html`<small>قُدِّم إلكترونياً ${fmtDateTime(t.createdAt)}</small>`}</td></tr></table></section>
    <section><h3>تفاصيل الطلب</h3>${blank ? '' : html`<p class="ef-subject"><b>الموضوع:</b> ${t.title}</p>`}
      <table class="ef-grid">${fields.filter((f) => !f.rows).map((f) => html`<tr><th style="width:30%">${f.label}</th><td>${v(f.value)}</td></tr>`)}</table>
      ${fields.filter((f) => f.rows).map((f) => html`<h4>${f.label}</h4>${table(f.cols || [], f.rows)}`)}
      ${persons.length ? html`<h4>الأشخاص المشمولون بالطلب</h4>${table(['الاسم', 'الرتبة', 'الرقم العسكري'], persons.map((p) => [p.name, p.rank, p.militaryNo]))}` : ''}
      <p class="ef-notes"><b>الملاحظات:</b> ${blank || !t.description ? raw(dots + dots) : t.description}</p></section>
    ${(form.signs && form.signs.length ? form.signs : EFORM_SIGNS).map((sg) => { const isTech = /الفني|الإجراء/.test(sg), u = isTech ? tech : {}; return html`<section class="ef-sign"><h3>${sg}</h3><table class="ef-grid">${who(u)}<tr><th>التاريخ</th><td>${isTech && done ? fmtDate(done.at) : raw(dots)}</td><th>التوقيع</th><td colspan="3">${raw(dots)}</td></tr></table>${isTech ? html`<p class="ef-notes"><b>الإجراء المتخذ:</b> ${done && done.text ? done.text : raw(dots + dots)}</p>` : ''}</section>`; })}
    ${(form.notes || []).filter(Boolean).length ? html`<section class="ef-tips"><h3>ملاحظات وتعليمات</h3><ul>${form.notes.filter(Boolean).map((n) => html`<li>${n}</li>`)}</ul></section>` : ''}
    <footer class="ef-foot">${s.supportPhone ? html`<span>الدعم الفني: <b class="ltr">${s.supportPhone}</b></span>` : ''}<span>${s.systemName || 'قسم تقنية المعلومات'} — استمارة إلكترونية${blank ? ' (نموذج فارغ)' : ` مرتبطة بالبلاغ ${t.number}`}</span></footer>
  </div>`;
};
